INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('3823129b-e7b5-4184-9c07-0fa70aec04f0', 'tenant_acme_01', 'KB0000017', 'SOP: User Password Reset (Linux/Unix)', NULL, 'User Management', NULL, 'Any Linux/Unix Server', 'Master SOP for resetting user passwords on any Linux/Unix server. Validates user exists, sets new password, optionally forces change on first login, and verifies password works.', '["Reset user password", "Password expired", "User locked out", "Forgot password", "Change password on server"]', 'User password has expired, been forgotten, or needs to be reset for security reasons.', '["ssh root@{ip} \"test -n ''{username}'' && ! echo ''{username}'' | grep -q ''{'' && echo GATE_USERNAME_VALID || echo GATE_ERROR_NO_USERNAME && exit 1\"", "ssh root@{ip} \"id -u {username} 2>/dev/null && echo USER_EXISTS || echo USER_NOT_FOUND\"", "ssh root@{ip} \"echo ''{username}:{password}'' | chpasswd 2>&1 && echo PASSWORD_SET_OK || echo PASSWORD_SET_FAILED\"", "ssh root@{ip} \"chage -d $(date +%Y-%m-%d) {username} 2>/dev/null && echo FORCE_CHANGE_OK || echo FORCE_CHANGE_SKIPPED\"", "ssh root@{ip} \"passwd -S {username} 2>/dev/null | head -1 && echo PASSWORD_STATUS_CHECKED\""]', 1, '[]', 'System Admin', 'Manual SOP', 0, 1, 5.0, FALSE, 1, '2026-08-01 22:13:12.633000', '2026-08-01 22:13:12.633000') ON CONFLICT DO NOTHING;
