INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('KB0000002', 'tenant_acme_01', 'KB0000002', 'SOP: Remove Local User Account ''Pablo'' and Home Directory on Linux Host 192.168.56.10', NULL, 'Server - Kernel & OS Patch', NULL, 'Unspecified CI', 'The local user account ''Pablo'' exists on the target Linux server (192.168.56.10) with an associated home directory at /home/Pablo. This account must be permanently removed from the system user database (/etc/passwd, /etc/shadow, /etc/group) and its file ownership cleaned up. The correction requires terminating any active processes owned by the user followed by executing ''userdel -r'' to remove the account and home directory recursively.', '["Entry for ''Pablo'' present in /etc/passwd with a valid UID/GID and home directory path /home/Pablo.", "Directory /home/Pablo exists and contains user profile data or application artifacts.", "Active processes listed under UID belonging to ''Pablo'' visible via ''ps -u Pablo'' or ''pgrep -u Pablo''.", "User ''Pablo'' appears in ''getent passwd Pablo'' output confirming NSS resolution."]', 'Standard identity lifecycle management request: The user account ''Pablo'' is no longer required on the infrastructure asset 192.168.56.10 and must be decommissioned to maintain least-privilege access hygiene and reclaim disk resources.', '["ssh root@192.168.56.10", "ssh root@192.168.56.10 \"id Pablo && getent passwd Pablo\"", "ssh root@192.168.56.10 \"pkill -9 -u Pablo; sleep 2\"", "ssh root@192.168.56.10 \"userdel -r Pablo\"", "ssh root@192.168.56.10 \"getent passwd Pablo; ls -ld /home/Pablo 2>/dev/null || echo ''Home directory removed''\""]', 1, '["INC0001026", "INC0001025", "INC0001024", "INC0001023", "INC0001022", "INC0001021", "INC0001020", "INC0001019", "INC0001018", "INC0001017"]', '🤖 NVIDIA Nemotron 3 550B Knowledge Agent', 'NVIDIA Nemotron 3 550B / Meta Llama 3.3 70B (NIM)', 0, 1, 5.0, FALSE, 1, '2026-08-01 09:38:49.250000', '2026-08-07 01:05:15.217000') ON CONFLICT DO NOTHING;
INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('KB0000001', 'tenant_acme_01', 'KB0000001', 'SOP: Python Virtualenv Creation and Snappy Environment Setup Runbook', NULL, 'Pending Triage', NULL, 'Unspecified CI', 'Procedure for creating, repairing, and activating Python virtual environment snappy under /opt/python_envs/snappy on Worker 1 192.168.56.10.', '["Python virtualenv snappy missing or corrupted on Worker 1. Need virtualenv creation SOP.", "Python virtual environment creation runbook snappy Worker 1", "Python virtualenv snappy missing or corrupted on Worker 1", "Create Nexacore ID on both control plane and Workernode1HL", "Create custom service user ID with permission to execute systemctl restart nexacore", "Provision single Linux user account with restricted systemctl restart command capability", "Create single user with /etc/sudoers.d drop-in permission for systemctl restart", "Linux User Account Provisioning & Passwordless Sudo Drop-in Setup", "Create user account on control plane and Workernode1HL"]', 'The prompt `((snappy) ) -bash-5.2#` is the default PS1 modification injected by the `activate` script of a Python virtual environment named ''snappy''. Since this triggers immediately upon interactive login for root, the activation command must be sourced in one of the login-shell initialization files: `/root/.bash_profile`, `/root/.profile`, `/root/.bashrc` (if sourced by the former), or a script in `/etc/profile.d/`. The resolution greps these specific locations, strips the offending `source`/`activate` line using sed, and validates the fix by spawning a fresh login shell (`bash -l`) to inspect the prompt.', '["ssh root@192.168.100.101 \"grep -r \"snappy\" /root/.bashrc /root/.bash_profile /root/.profile /etc/profile.d/ 2>/dev/null | grep -v \"Binary\"\"", "ssh root@192.168.100.101 \"sed -i ''/snappy\\/bin\\/activate/d'' /root/.bashrc /root/.bash_profile /root/.profile 2>/dev/null; for f in /etc/profile.d/*.sh; do sed -i ''/snappy\\/bin\\/activate/d'' \"$f\"; done\"", "ssh root@192.168.100.101 \"bash -l -c ''echo $PS1'' | grep -q \"snappy\" && echo \"FAIL: Venv still active in login shell\" || echo \"SUCCESS: Venv activation removed\"\"", "ssh root@192.168.100.101 \"exec bash -l\""]', 1, '["INC0001036", "INC0001035", "INC0001034", "INC0001035", "INC0001034", "INC0001033", "INC0001032", "INC0001031", "INC0001030", "INC0001027"]', '🤖 Unix Auto-Resolver Agent', 'nvidia/nemotron-3-ultra-550b-a55b', 0, 1, 5.0, FALSE, 1, '2026-08-01 09:38:24.453000', '2026-08-07 01:05:15.339000') ON CONFLICT DO NOTHING;
INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('874ffae1-9e82-4521-adc8-6c29e11eea92', 'tenant_acme_01', 'KB0000014', 'Troubleshooting & SOP: AWS East Region DB Connection Timeout', NULL, 'Pending Triage', NULL, 'router-border-nyc-01', 'Standard Operating Procedure to diagnose and resolve AWS East Region DB Connection Timeout service issues.', '["Service AWS East Region DB Connection Timeout reported degraded state", "Connection timeouts or refused connections in logs."]', 'Improper configuration settings, corrupted state files, or service crash due to memory pressure.', '["ssh root@192.168.100.101 \"Log in to the target system and verify service process status: ''ps aux | grep AWS'' or systemctl status.\"", "ssh root@192.168.100.101 \"Inspect logs using journalctl or logs in /var/log/ to identify specific errors.\"", "ssh root@192.168.100.101 \"Restart the affected service process and verify it binds successfully to its network port.\"", "ssh root@192.168.100.101 \"Confirm the service state remains healthy and operational metrics return to baseline.\""]', 1, '["INC0000916", "INC0000915", "INC0000914", "INC0000913", "INC0000912", "INC0000911", "INC0000910", "INC0000909", "INC0000908", "INC0000907"]', '🤖 NVIDIA Nemotron 3 550B Knowledge Agent', 'NVIDIA Nemotron 3 550B / Meta Llama 3.3 70B (NIM)', 0, 1, 5.0, FALSE, 1, '2026-08-01 21:29:08.511000', '2026-08-07 01:05:13.716000') ON CONFLICT DO NOTHING;
INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('KB0000003', 'tenant_acme_01', 'KB0000003', 'SOP: NexaCore Port 8080 Firewalld Unblock and Subprocess Restart', NULL, 'Server - Kernel & OS Patch', NULL, 'Worker 1', 'Procedure for unblocking firewalld port 8080, terminating orphaned python http processes, and restarting NexaCore web portal on worker1OL 192.168.56.10.', '["NexaCore Enterprise Portal unreachable on worker1OL port 8080. Connection refused.", "NexaCore port 8080 down firewalld block"]', 'Improper configuration settings, corrupted state files, or service crash due to memory pressure.', '["ssh root@192.168.100.101 \"Log in to the target system and verify service process status: ''ps aux | grep Unix'' or systemctl status.\"", "ssh root@192.168.100.101 \"Inspect logs using journalctl or logs in /var/log/ to identify specific errors.\"", "ssh root@192.168.100.101 \"Restart the affected service process and verify it binds successfully to its network port.\"", "ssh root@192.168.100.101 \"Confirm the service state remains healthy and operational metrics return to baseline.\""]', 1, '["INC0001016", "INC0001015", "INC0001014", "INC0001013", "INC0001012", "INC0001011", "INC0001010", "INC0001009", "INC0001008", "INC0001007"]', '🤖 NVIDIA Nemotron 3 550B Knowledge Agent', 'NVIDIA Nemotron 3 550B / Meta Llama 3.3 70B (NIM)', 0, 2, 5.0, FALSE, 1, '2026-08-01 09:39:25.786000', '2026-08-07 01:05:15.097000') ON CONFLICT DO NOTHING;
INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('db50a454-9a52-49a7-bef2-5fa47a7ca2c2', 'tenant_acme_01', 'KB0000019', 'Master SOP: Create Python Virtual Environment and Install Required Packages', NULL, 'Unix - OS & System Service', NULL, 'Worker 1', 'Generic Master Standard Operating Procedure for creating Python virtual environments (venv), upgrading pip, installing requested packages (e.g. chromadb, pandas, openpyxl, numpy, requests, flask), and verifying package import health across Linux target hosts.', '["Create Python virtual environment", "create a python virtual environment called {venv_name}", "install python packages in virtual environment", "python virtualenv creation and package setup runbook", "python3 -m venv setup and pip install"]', 'Root cause identified in approved new use case diagnostic.', '["python3 --version && python3 -m venv --help >/dev/null 2>&1 || (apt-get update && apt-get install -y python3-venv 2>/dev/null || yum install -y python3-venv 2>/dev/null || dnf install -y python3-venv 2>/dev/null)", "mkdir -p /opt/{venv_name}", "python3 -m venv /opt/{venv_name}", "/opt/{venv_name}/bin/pip install --upgrade pip", "/opt/{venv_name}/bin/pip install {packages}", "/opt/{venv_name}/bin/python -c \"import sys; print(''Virtual environment {venv_name} ready:'', sys.version)\""]', 1, '["5515db3c-2300-4ebb-9d8c-6055cab27bb1"]', '🤖 Gemini 3.1 Pro Knowledge Synthesis Agent', 'azure_ai/genailab-maas-Llama-3.3-70B-Instruct', 0, 0, 5.0, FALSE, 1, '2026-08-05 06:11:24.622000', '2026-08-05 06:20:30.469000') ON CONFLICT DO NOTHING;
