INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('748cf2d1-c490-460d-b59b-9e7a95b837f8', 'tenant_acme_01', 'KB0000046', 'SOP: Provision 20 Restricted Service Accounts for Nexacore Restart on WorkerNode1HL', NULL, 'Unix - OS & System Service', NULL, 'WorkerNode1HL', 'Provision 20 standard user accounts (User01–User20) on WorkerNode1HL (192.168.100.102) with highly restricted sudo privileges allowing execution of only ''systemctl restart Nexacore''. No shell access restrictions beyond standard user defaults; sudoers entries are validated via visudo to prevent syntax errors.', '["Alert logged for create 20 User IDs USer01, User02.... User20. which has execution rights to only command \"systemctl restart Nexacore\" on workernode1HL. "]', 'Root cause identified in approved new use case diagnostic.', '["ssh root@192.168.100.102 \"for i in $(seq -w 1 20); do user=\"User$i\"; id -u \"$user\" &>/dev/null || useradd -m -s /bin/bash -c \"Nexacore Restart Operator $i\" \"$user\"; done\"", "ssh root@192.168.100.102 \"for i in $(seq -w 1 20); do user=\"User$i\"; mkdir -p \"/home/$user/.ssh\" && chmod 700 \"/home/$user/.ssh\" && chown -R \"$user:$user\" \"/home/$user/.ssh\"; done\"", "ssh root@192.168.100.102 \"for i in $(seq -w 1 20); do user=\"User$i\"; echo \"$user ALL=(ALL) NOPASSWD: /bin/systemctl restart Nexacore\" > \"/etc/sudoers.d/99-$user-nexacore-restart\" && chmod 440 \"/etc/sudoers.d/99-$user-nexacore-restart\" && visudo -c -f \"/etc/sudoers.d/99-$user-nexacore-restart\"; done\"", "ssh root@192.168.100.102 \"for i in $(seq -w 1 20); do user=\"User$i\"; id \"$user\" && ls -ld \"/home/$user\"; done\""]', 1, '["b78db96a-468e-4963-abcd-2206be58a5b3"]', '🤖 Gemini 3.1 Pro Knowledge Synthesis Agent', 'azure_ai/genailab-maas-Llama-3.3-70B-Instruct', 0, 1, 5.0, FALSE, 1, '2026-08-08 18:56:36.975000', '2026-08-08 18:56:36.975000') ON CONFLICT DO NOTHING;
INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('1cc876a0-0615-45e4-a964-7628f9e63628', 'tenant_acme_01', 'KB0468209', 'Master SOP: Unix - OS & System Service', NULL, 'Unix - OS & System Service', NULL, 'WorkerNode1HL', 'Standard Operating Procedure to diagnose and resolve Unix - OS & System Service service issues.', '["Alert logged for User ID deletion for Srinath on WorkerNode1HL", "Alert logged for offboard user siva from Workernode1HL"]', 'Root cause identified in approved new use case diagnostic.', '["ssh root@192.168.100.102 \"tar -czf /root/Srinath_archive_$(date +%F).tar.gz -C /home Srinath 2>/dev/null || true\"", "ssh root@192.168.100.102 \"rm -f /etc/sudoers.d/Srinath /etc/sudoers.d/99-Srinath || true\"", "ssh root@192.168.100.102 \"userdel -r -f Srinath 2>/dev/null || true\"", "ssh root@192.168.100.102 \"id Srinath 2>/dev/null && echo ''User still exists'' || echo ''User successfully deleted''\"", "ssh root@192.168.100.102 \"tar -czf /root/siva_archive_$(date +%F).tar.gz -C /home siva 2>/dev/null || true\"", "ssh root@192.168.100.102 \"rm -f /etc/sudoers.d/siva /etc/sudoers.d/99-siva || true\"", "ssh root@192.168.100.102 \"userdel -r -f siva 2>/dev/null || true\"", "ssh root@192.168.100.102 \"id siva 2>/dev/null && echo ''User still exists'' || echo ''User successfully deleted''\""]', 44, '["KB0468209", "KB0000023", "KB0000022"]', '🤖 Knowledge Consolidator Agent', 'nvidia/nemotron-3-ultra-550b-a55b', 0, 0, 5.0, FALSE, 1, '2026-08-07 05:33:10.558000', '2026-08-10 05:42:18.670000') ON CONFLICT DO NOTHING;
