INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('6985debc-b3b0-45cd-a7c7-9038c024e6b3', 'tenant_acme_01', 'KB0000024', 'Master SOP: User Management', NULL, 'User Management', NULL, 'Any Linux/Unix Server', 'Standard Operating Procedure to diagnose and resolve User Management service issues.', '["Reset user password", "Password expired", "User locked out", "Forgot password", "Change password on server", "Lock user account", "Unlock user account", "Disable user login", "Enable user login", "Account security lock"]', 'User password has expired, been forgotten, or needs to be reset for security reasons.', '["ssh root@{ip} \"test -n ''{username}'' && ! echo ''{username}'' | grep -q ''{'' && echo GATE_USERNAME_VALID || echo GATE_ERROR_NO_USERNAME && exit 1\"", "ssh root@{ip} \"id -u {username} 2>/dev/null && echo USER_EXISTS || echo USER_NOT_FOUND\"", "ssh root@{ip} \"echo ''{username}:{password}'' | chpasswd 2>&1 && echo PASSWORD_SET_OK || echo PASSWORD_SET_FAILED\"", "ssh root@{ip} \"chage -d $(date +%Y-%m-%d) {username} 2>/dev/null && echo FORCE_CHANGE_OK || echo FORCE_CHANGE_SKIPPED\"", "ssh root@{ip} \"passwd -S {username} 2>/dev/null | head -1 && echo PASSWORD_STATUS_CHECKED\"", "ssh root@{ip} \"passwd -S {username} 2>/dev/null | head -1 && echo PASSWORD_STATUS_BEFORE\"", "ssh root@{ip} \"{lock_unlock_command}\"", "ssh root@{ip} \"passwd -S {username} 2>/dev/null | head -1 && echo PASSWORD_STATUS_AFTER\"", "ssh root@{ip} \"su - {username} -c ''echo LOGIN_TEST_OK'' 2>&1 | head -1 && echo LOGIN_TEST_COMPLETE || echo LOGIN_TEST_BLOCKED\""]', 26, '["KB0000017", "KB0000024"]', '🤖 Knowledge Consolidator Agent', 'nvidia/nemotron-3-ultra-550b-a55b', 0, 0, 5.0, FALSE, 1, '2026-08-05 23:51:04.685000', '2026-08-10 05:42:18.643000') ON CONFLICT DO NOTHING;
INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('2a431140-c92b-4c47-988d-fc526341f00e', 'tenant_acme_01', 'KB0000036', 'Master SOP: Create Linux Users with Restricted Sudo Command Execution', NULL, 'Unix - OS & System Service', NULL, 'control plane', 'Based on live server diagnostics (CentOS Stream 10, kernel 6.12, control plane hosting Kubernetes components), this SOP provisions multiple user accounts with sudo privileges to execute a specific command (e.g., ''su - jboss'') without password. The procedure ensures idempotent user creation, secure sudoers.d configuration, and validation of syntax and user existence.', '["Alert logged for create 5 users Thycotic1 to Thycotic5 , which has the capabality to execute command like su - jboss on ControlPlane", "Create Nexacore ID on both control plane and Workernode1HL", "Create custom service user ID with permission to execute systemctl restart nexacore", "Provision single Linux user account with restricted systemctl restart command capability", "Create single user with /etc/sudoers.d drop-in permission for systemctl restart", "Linux User Account Provisioning & Passwordless Sudo Drop-in Setup", "Create user account on control plane and Workernode1HL"]', 'Root cause identified in approved new use case diagnostic.', '["ssh root@192.168.100.101 \"id -u {username} &>/dev/null || useradd -m -s /bin/bash {username}\"", "ssh root@192.168.100.101 \"echo ''{username} ALL=(ALL) NOPASSWD: {sudo_command}'' > /etc/sudoers.d/99-{username}\"", "ssh root@192.168.100.101 \"chmod 440 /etc/sudoers.d/99-{username}\"", "ssh root@192.168.100.101 \"visudo -c\"", "ssh root@192.168.100.102 \"for i in $(seq -w 1 20); do user=\"User$i\"; id -u \"$user\" &>/dev/null || useradd -m -s /bin/bash -c \"Nexacore Restart Operator $i\" \"$user\"; done\"", "ssh root@192.168.100.102 \"for i in $(seq -w 1 20); do user=\"User$i\"; mkdir -p \"/home/$user/.ssh\" && chmod 700 \"/home/$user/.ssh\" && chown -R \"$user:$user\" \"/home/$user/.ssh\"; done\"", "ssh root@192.168.100.102 \"for i in $(seq -w 1 20); do user=\"User$i\"; echo \"$user ALL=(ALL) NOPASSWD: /bin/systemctl restart Nexacore\" > \"/etc/sudoers.d/99-$user-nexacore-restart\" && chmod 440 \"/etc/sudoers.d/99-$user-nexacore-restart\" && visudo -c -f \"/etc/sudoers.d/99-$user-nexacore-restart\"; done\"", "ssh root@192.168.100.102 \"for i in $(seq -w 1 20); do user=\"User$i\"; id \"$user\" && ls -ld \"/home/$user\"; done\"", "ssh root@192.168.100.101 \"useradd -m -s /bin/bash -c \"Asha Operations\" asha && useradd -m -s /bin/bash -c \"Praneeth Operations\" praneeth\"", "ssh root@192.168.100.101 \"mkdir -p /home/asha/.ssh /home/praneeth/.ssh && chmod 700 /home/asha/.ssh /home/praneeth/.ssh\"", "ssh root@192.168.100.101 \"echo \"ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAI... asha@corp\" > /home/asha/.ssh/authorized_keys && echo \"ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAI... praneeth@corp\" > /home/praneeth/.ssh/authorized_keys\"", "ssh root@192.168.100.101 \"chmod 600 /home/asha/.ssh/authorized_keys /home/praneeth/.ssh/authorized_keys && chown -R asha:asha /home/asha/.ssh && chown -R praneeth:praneeth /home/praneeth/.ssh\"", "ssh root@192.168.100.101 \"echo ''asha ALL=(ALL) NOPASSWD:ALL'' > /etc/sudoers.d/asha && echo ''praneeth ALL=(ALL) NOPASSWD:ALL'' > /etc/sudoers.d/praneeth && chmod 440 /etc/sudoers.d/asha /etc/sudoers.d/praneeth && visudo -c\"", "ssh root@192.168.100.101 \"for user in asha Praneeth; do id -u \"$user\" &>/dev/null || useradd -m -s /bin/bash -G wheel \"$user\"; done\"", "ssh root@192.168.100.101 \"for user in asha Praneeth; do mkdir -p /home/\"$user\"/.ssh; chmod 700 /home/\"$user\"/.ssh; chown \"$user\":\"$user\" /home/\"$user\"/.ssh; done\"", "ssh root@192.168.100.101 \"cat > /home/asha/.ssh/authorized_keys << ''EOF''\nssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAABAQ... asha@workstation\nEOF\ncat > /home/Praneeth/.ssh/authorized_keys << ''EOF''\nssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAABAQ... Praneeth@workstation\nEOF\"", "ssh root@192.168.100.101 \"for user in asha Praneeth; do chmod 600 /home/\"$user\"/.ssh/authorized_keys; chown \"$user\":\"$user\" /home/\"$user\"/.ssh/authorized_keys; done && visudo -c\"", "ssh root@192.168.100.101 \"id -u venu &>/dev/null || useradd -m -s /bin/bash -c \"Project XYZ Automation\" venu\"", "ssh root@192.168.100.101 \"echo ''venu ALL=(ALL) NOPASSWD:ALL'' > /etc/sudoers.d/90-venu-xyz && chmod 440 /etc/sudoers.d/90-venu-xyz\"", "ssh root@192.168.100.101 \"visudo -c -f /etc/sudoers.d/90-venu-xyz\"", "ssh root@192.168.100.101 \"su - venu -c ''sudo -n whoami''\"", "ssh root@192.168.100.101 \"mkdir -p /home/venu/.ssh && chmod 700 /home/venu/.ssh && chown venu:venu /home/venu/.ssh\"", "ssh root@192.168.100.101 \"echo ''venu ALL=(ALL) NOPASSWD:ALL'' > /etc/sudoers.d/99-venu-xyz && chmod 440 /etc/sudoers.d/99-venu-xyz\"", "ssh root@192.168.100.101 \"visudo -c -f /etc/sudoers.d/99-venu-xyz && echo ''User venu provisioned with passwordless sudo.''\"", "ssh root@{ip} \"id -u {username} &>/dev/null || useradd -m -s /bin/bash -c ''{username} Account'' {username}\"", "ssh root@{ip} \"echo ''{username}:{password}'' | chpasswd || true\"", "ssh root@{ip} \"mkdir -p /home/{username}/.ssh && chmod 700 /home/{username}/.ssh && chown -R {username}:{username} /home/{username}/.ssh\"", "ssh root@{ip} \"echo ''{username} ALL=(ALL) NOPASSWD:ALL'' > /etc/sudoers.d/99-{username} && chmod 440 /etc/sudoers.d/99-{username} && visudo -c -f /etc/sudoers.d/99-{username}\"", "ssh root@{ip} \"id {username} && ls -ld /home/{username}\"", "ssh root@192.168.100.101 \"id -u venu &>/dev/null || useradd -m -s /bin/bash -c \"Project XYZ Automation\" venu && passwd -l venu\"", "ssh root@192.168.100.101 \"mkdir -p /home/venu/.ssh && chmod 700 /home/venu/.ssh && touch /home/venu/.ssh/authorized_keys && chmod 600 /home/venu/.ssh/authorized_keys && chown -R venu:venu /home/venu/.ssh\"", "ssh root@192.168.100.101 \"cat > /etc/sudoers.d/99-venu-xyz <<''EOF''\nvenu ALL=(ALL) NOPASSWD:ALL\nEOF\"", "ssh root@192.168.100.101 \"visudo -c -f /etc/sudoers.d/99-venu-xyz && chmod 440 /etc/sudoers.d/99-venu-xyz\""]', 18502, '["KB0000046", "KB0000020", "KB0000036", "KB0000028", "KB0000016", "KB0000027", "KB0000006", "KB0000021", "KB0000030", "KB0000029"]', '🤖 Gemini 3.1 Pro Knowledge Synthesis Agent', 'azure_ai/genailab-maas-Llama-3.3-70B-Instruct', 0, 1, 5.0, FALSE, 1, '2026-08-09 22:21:02.034000', '2026-08-10 05:06:54.207000') ON CONFLICT DO NOTHING;
INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('a46f4a86-e557-4702-9731-d8cd98804dbf', 'tenant_acme_01', 'KB0000038', 'Master SOP: Bulk & Single Linux User Account Deprovisioning & Deletion', NULL, 'User Management', NULL, NULL, 'Generic Master Standard Operating Procedure for securely removing single or bulk local user accounts, terminating active processes, removing home directories, and purging sudoers drop-in files across Linux nodes.', '["Delete Linux user account", "User deprovisioning and account removal", "delete user {username}", "Delete 500 users like User001 to User500", "Delete all the users mentioned below", "offboard user account"]', NULL, '["rm -f /etc/sudoers.d/{username} /etc/sudoers.d/99-{username}", "pkill -9 -u {username} 2>/dev/null || true", "userdel -r -f {username} 2>/dev/null || true"]', NULL, NULL, 'System Admin', NULL, 0, 0, 5.0, FALSE, 1, '2026-08-09 22:08:05.848000', '2026-08-09 22:08:05.848000') ON CONFLICT DO NOTHING;
INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('f43ffdee-f00b-4331-bc0f-847d9ce719be', 'tenant_acme_01', 'KB0000039', 'Master SOP: Kubernetes & ArgoCD Service Health Restoration', NULL, 'Unix - OS & System Service', NULL, 'control plane', 'Generic Master Standard Operating Procedure for diagnosing and restoring ArgoCD application controller, server pods, and Kubernetes cluster deployments across control plane and worker nodes.', '["ArgoCD application controller issue", "Kubernetes namespace health restoration", "kubectl rollout restart deployment", "argocd namespace pod crash", "Kubernetes cluster recovery"]', 'Root cause identified in approved new use case diagnostic.', '["kubectl get namespaces", "kubectl get pods -n {target_ns} -o wide", "kubectl rollout restart deployment -n {target_ns}", "kubectl get events -n {target_ns} --sort-by=''.metadata.creationTimestamp'' | tail -n 10", "kubectl get pods -n {target_ns}"]', 3, '["KB0000039", "KB0000041"]', '🤖 Gemini 3.1 Pro Knowledge Synthesis Agent', 'azure_ai/genailab-maas-Llama-3.3-70B-Instruct', 0, 1, 5.0, FALSE, 1, '2026-08-10 05:10:08.444000', '2026-08-10 05:42:18.676000') ON CONFLICT DO NOTHING;
INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('b7d6e5d2-6e56-43b7-8835-97a4c40240d8', 'tenant_acme_01', 'KB0000040', 'Master SOP: Retrieve ArgoCD Admin Credentials for Control Plane Cluster', NULL, 'Unix - OS & System Service', NULL, 'control plane', 'The diagnostic findings show ArgoCD repo-server processes running and a Python port proxy listening on port 8088, indicating ArgoCD is deployed on the control plane Kubernetes cluster. The admin password is stored in the ''argocd-initial-admin-secret'' secret in the argocd namespace. Since kubectl commands were blocked during diagnostics, remediation requires executing kubectl commands to retrieve and decode the password.', '["Alert logged for There is an Argocd application running the controlplane kuberenetes cluster. I need login details of it. "]', 'Root cause identified in approved new use case diagnostic.', '["ssh root@192.168.100.101 \"kubectl get secret argocd-initial-admin-secret -n argocd -o jsonpath=''{.data.password}'' | base64 -d && echo\"", "ssh root@192.168.100.101 \"kubectl get pods -n argocd -l app.kubernetes.io/name=argocd-server -o wide\"", "ssh root@192.168.100.101 \"kubectl port-forward svc/argocd-server -n argocd 8080:443 --address=0.0.0.0 &\"", "ssh root@192.168.56.10 \"python3 --version && python3 -m venv --help >/dev/null 2>&1 || (apt-get update && apt-get install -y python3-venv 2>/dev/null || yum install -y python3-venv 2>/dev/null || dnf install -y python3-venv 2>/dev/null)\"", "ssh root@192.168.56.10 \"mkdir -p /opt/snappy\"", "ssh root@192.168.56.10 \"python3 -m venv /opt/snappy\"", "ssh root@192.168.56.10 \"/opt/snappy/bin/pip install --upgrade pip\"", "ssh root@192.168.56.10 \"/opt/snappy/bin/pip install pandas openpyxl\"", "ssh root@192.168.56.10 \"/opt/snappy/bin/python -c \"import pandas; import openpyxl; print(''pandas version:'', pandas.__version__); print(''openpyxl version:'', openpyxl.__version__)\"\""]', 3, '["KB0000019", "KB0000040"]', '🤖 Gemini 3.1 Pro Knowledge Synthesis Agent', 'azure_ai/genailab-maas-Llama-3.3-70B-Instruct', 0, 1, 5.0, FALSE, 1, '2026-08-10 05:15:09.020000', '2026-08-10 05:42:18.654000') ON CONFLICT DO NOTHING;
INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('f142f8fb-5b6a-4fd0-bd66-295217c4edbf', 'tenant_acme_01', 'KB0000025', 'Master SOP: IBM DB2 User Provisioning, Access Levels & CloudBeaver / Beaver UI Access', 'Master SOP: IBM DB2 Database User Lifecycle Management (Creation, Deletion, Deprovisioning & CloudBeaver / Beaver Access)
INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('f8b6cded-10f9-4edc-a5a9-97aae1edc00c', 'tenant_acme_01', 'KB0468210', 'Master SOP: System Performance & Resource Utilization Runbook', NULL, 'System Performance Issue', NULL, 'WorkerNode1HL', 'Generic Master Standard Operating Procedure for diagnosing and resolving high CPU utilization, high memory consumption, storage space alerts, and process bottlenecks across Linux servers.', '["CPU 100% utilization", "Memory 100% utilization", "High CPU utilization alert", "High RAM utilization alert", "System performance issue"]', 'High memory consumption by application or OS processes.', '["uptime", "ps aux --sort=-%cpu | head -n 10", "free -m", "df -h", "journalctl -n 30 --no-pager"]', 0, '["KB0468207", "KB0051346"]', '🤖 Knowledge Consolidator Agent', 'nvidia/nemotron-3-ultra-550b-a55b', 0, 0, 5.0, FALSE, 1, '2026-08-07 05:33:11.403000', '2026-08-10 05:42:19.537000') ON CONFLICT DO NOTHING;
INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('a8e81cbe-c08c-4c87-a381-e4bda67e6f67', 'tenant_acme_01', 'KB0000041', 'Master SOP: Jenkins Credential Retrieval & Service Verification', NULL, 'Unix - OS & System Service', NULL, 'WorkerNode1HL', 'Generic Master Standard Operating Procedure to retrieve Jenkins admin credentials, initialAdminPassword, API secrets, and verify Jenkins server process health across control plane and worker nodes.', '["Jenkins server credentials needed", "retrieve Jenkins username and password", "locate initialAdminPassword", "Jenkins login credentials", "Jenkins service status"]', 'Root cause identified in approved new use case diagnostic.', '["ps aux | grep -i jenkins", "ss -tulpn | grep 8080", "cat /var/lib/jenkins/secrets/initialAdminPassword 2>/dev/null || cat /root/.jenkins/secrets/initialAdminPassword 2>/dev/null || find / -name initialAdminPassword 2>/dev/null"]', 1, '["6f499427-2387-4931-99ea-ef442bcffb2c"]', '🤖 Gemini 3.1 Pro Knowledge Synthesis Agent', 'azure_ai/genailab-maas-Llama-3.3-70B-Instruct', 0, 1, 5.0, FALSE, 1, '2026-08-10 05:36:14.746000', '2026-08-10 05:36:14.746000') ON CONFLICT DO NOTHING;
INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('8fcabd16-cef3-4160-bf4e-ce15d4ed39f3', 'tenant_acme_01', 'KB0000026', 'Kubernetes Node & Kubelet Recovery SOP', NULL, 'Server - Kernel & OS Patch', NULL, 'router-border-nyc-01', 'Guidance for resolving Kubelet daemon failures, node NotReady states, and container runtime communication issues.', '["Kubernetes worker node status transitions to ''NotReady''.", "Kubelet service fails to start or reports connection refused to API server.", "Container runtime endpoints timed out in logs."]', 'Kubelet certificate expiration, swap space enabled blocking kubelet startup, or containerd service crash.', '["ssh root@192.168.100.101 \"Inspect kubelet status: ''systemctl status kubelet''\"", "ssh root@192.168.100.101 \"Check containerd state and restart if dead: ''systemctl restart containerd''\"", "ssh root@192.168.100.101 \"Disable swap space if enabled: ''swapoff -a''\"", "ssh root@192.168.100.101 \"View kubelet logs for exact API server handshake failures: ''journalctl -u kubelet -n 50 --no-pager''\"", "ssh root@192.168.100.101 \"Restart kubelet daemon: ''systemctl restart kubelet'' and verify node status with ''kubectl get nodes''\""]', 1, '["INC0000016", "INC0000015", "INC0000014", "INC0000013", "INC0000012", "INC0000011", "INC0000010", "INC0000009", "INC0000008", "INC0000007"]', '🤖 NVIDIA Nemotron 3 550B Knowledge Agent', 'NVIDIA Nemotron 3 550B / Meta Llama 3.3 70B (NIM)', 0, 0, 5.0, FALSE, 1, '2026-08-06 22:56:19.224000', '2026-08-07 01:05:13.248000') ON CONFLICT DO NOTHING;
INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('51ee9538-dc64-4455-b0e6-49134644eb8f', 'tenant_acme_01', 'KB0000016', 'Provision User ''venu'' with Passwordless Sudo via /etc/sudoers.d Drop-in File on Control Plane 192.168.100.101', NULL, 'Unix - OS & System Service', NULL, 'control plane', 'The control plane server lacks the required service account ''venu'' with NOPASSWD sudo privileges for Project XYZ automation pipelines. This procedure creates the user, configures a dedicated sudoers drop-in file under /etc/sudoers.d/ to grant unrestricted passwordless root execution, and validates the configuration syntax to prevent lockout.', '["Alert logged for create user ID venu with passwordless elevated previleges on control plane server for project XYZ"]', 'Root cause identified in approved new use case diagnostic.', '["ssh root@192.168.100.101 \"id -u venu &>/dev/null || useradd -m -s /bin/bash -c \"Project XYZ Automation\" venu\"", "ssh root@192.168.100.101 \"echo ''venu ALL=(ALL) NOPASSWD:ALL'' > /etc/sudoers.d/90-venu-xyz && chmod 440 /etc/sudoers.d/90-venu-xyz\"", "ssh root@192.168.100.101 \"visudo -c -f /etc/sudoers.d/90-venu-xyz\"", "ssh root@192.168.100.101 \"su - venu -c ''sudo -n whoami''\""]', 1, '["INC0001034"]', '🤖 Gemini 3.1 Pro Knowledge Synthesis Agent', 'azure_ai/genailab-maas-Llama-3.3-70B-Instruct', 0, 1, 5.0, FALSE, 1, '2026-08-01 21:29:10.577000', '2026-08-07 01:05:13.477000') ON CONFLICT DO NOTHING;
INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('c84056ea-b5db-45e7-a62b-aa83eb0b0030', 'tenant_acme_01', 'KB0000015', 'Troubleshooting & SOP: VPN Gateway Certificate Expiration Alert', NULL, 'Pending Triage', NULL, 'postgres-prod-01', 'Standard Operating Procedure to diagnose and resolve VPN Gateway Certificate Expiration Alert service issues.', '["Service VPN Gateway Certificate Expiration Alert reported degraded state", "Connection timeouts or refused connections in logs."]', 'Improper configuration settings, corrupted state files, or service crash due to memory pressure.', '["ssh root@192.168.100.101 \"Log in to the target system and verify service process status: ''ps aux | grep VPN'' or systemctl status.\"", "ssh root@192.168.100.101 \"Inspect logs using journalctl or logs in /var/log/ to identify specific errors.\"", "ssh root@192.168.100.101 \"Restart the affected service process and verify it binds successfully to its network port.\"", "ssh root@192.168.100.101 \"Confirm the service state remains healthy and operational metrics return to baseline.\""]', 1, '["INC0000906", "INC0000905", "INC0000904", "INC0000903", "INC0000902", "INC0000901", "INC0000900", "INC0000899", "INC0000898", "INC0000897"]', '🤖 NVIDIA Nemotron 3 550B Knowledge Agent', 'NVIDIA Nemotron 3 550B / Meta Llama 3.3 70B (NIM)', 0, 1, 5.0, FALSE, 1, '2026-08-01 21:29:09.537000', '2026-08-07 01:05:13.597000') ON CONFLICT DO NOTHING;
