INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('KB0000012', 'tenant_acme_01', 'KB0000012', 'Troubleshooting & SOP: SAP ERP Financials SSO Auth Failure', NULL, 'Pending Triage', NULL, 'postgres-prod-01', 'Standard Operating Procedure to diagnose and resolve SAP ERP Financials SSO Auth Failure service issues.', '["Service SAP ERP Financials SSO Auth Failure reported degraded state", "Connection timeouts or refused connections in logs."]', 'Improper configuration settings, corrupted state files, or service crash due to memory pressure.', '["ssh root@192.168.100.101 \"Log in to the target system and verify service process status: ''ps aux | grep SAP'' or systemctl status.\"", "ssh root@192.168.100.101 \"Inspect logs using journalctl or logs in /var/log/ to identify specific errors.\"", "ssh root@192.168.100.101 \"Restart the affected service process and verify it binds successfully to its network port.\"", "ssh root@192.168.100.101 \"Confirm the service state remains healthy and operational metrics return to baseline.\""]', 1, '["INC0000936", "INC0000935", "INC0000934", "INC0000933", "INC0000932", "INC0000931", "INC0000930", "INC0000929", "INC0000928", "INC0000927"]', '🤖 NVIDIA Nemotron 3 550B Knowledge Agent', 'NVIDIA Nemotron 3 550B / Meta Llama 3.3 70B (NIM)', 0, 1, 5.0, FALSE, 1, '2026-08-01 09:43:48.911000', '2026-08-07 01:05:14.021000') ON CONFLICT DO NOTHING;
INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('KB0000008', 'tenant_acme_01', 'KB0000008', 'Troubleshooting & SOP: Active Directory LDAP Sync Failure', NULL, 'Pending Triage', NULL, 'router-border-nyc-01', 'Standard Operating Procedure to diagnose and resolve Active Directory LDAP Sync Failure service issues.', '["Service Active Directory LDAP Sync Failure reported degraded state", "Connection timeouts or refused connections in logs."]', 'Improper configuration settings, corrupted state files, or service crash due to memory pressure.', '["ssh root@192.168.100.101 \"Log in to the target system and verify service process status: ''ps aux | grep Active'' or systemctl status.\"", "ssh root@192.168.100.101 \"Inspect logs using journalctl or logs in /var/log/ to identify specific errors.\"", "ssh root@192.168.100.101 \"Restart the affected service process and verify it binds successfully to its network port.\"", "ssh root@192.168.100.101 \"Confirm the service state remains healthy and operational metrics return to baseline.\""]', 1, '["INC0000976", "INC0000975", "INC0000974", "INC0000973", "INC0000972", "INC0000971", "INC0000970", "INC0000969", "INC0000968", "INC0000967"]', '🤖 NVIDIA Nemotron 3 550B Knowledge Agent', 'NVIDIA Nemotron 3 550B / Meta Llama 3.3 70B (NIM)', 0, 1, 5.0, FALSE, 1, '2026-08-01 09:41:57.697000', '2026-08-07 01:05:14.503000') ON CONFLICT DO NOTHING;
INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('KB0000006', 'tenant_acme_01', 'KB0000006', 'Create User ''venu'' with Passwordless Sudo via Drop-in File on Control Plane Node 192.168.100.101', NULL, 'Unix - OS & System Service', NULL, 'control plane', 'The control plane node lacks the service account ''venu'' required for Project XYZ automation workflows. This procedure creates the user with a locked password, configures a dedicated sudoers drop-in file under /etc/sudoers.d/ for passwordless root escalation, and validates the sudo token acquisition without TTY requirement.', '["Alert logged for create user ID venu with passwordless elevated previleges on control plane server for project XYZ"]', 'Root cause identified in approved new use case diagnostic.', '["ssh root@192.168.100.101 \"id -u venu &>/dev/null || useradd -m -s /bin/bash -c \"Project XYZ Automation\" venu\"", "ssh root@192.168.100.101 \"mkdir -p /home/venu/.ssh && chmod 700 /home/venu/.ssh && chown venu:venu /home/venu/.ssh\"", "ssh root@192.168.100.101 \"echo ''venu ALL=(ALL) NOPASSWD:ALL'' > /etc/sudoers.d/99-venu-xyz && chmod 440 /etc/sudoers.d/99-venu-xyz\"", "ssh root@192.168.100.101 \"visudo -c -f /etc/sudoers.d/99-venu-xyz && echo ''User venu provisioned with passwordless sudo.''\""]', 1, '["INC0001034"]', '🤖 Gemini 3.1 Pro Knowledge Synthesis Agent', 'azure_ai/genailab-maas-Llama-3.3-70B-Instruct', 0, 1, 5.0, FALSE, 1, '2026-08-01 09:40:26.198000', '2026-08-07 01:05:14.743000') ON CONFLICT DO NOTHING;
INSERT INTO "KnowledgeArticle" ("updatedAt", "symptoms", "resolutionSteps", "workNotesAnalyzedCount", "sourceIncidentIds", "helpfulCount", "viewsCount", "rating", "isPublished", "version", "createdAt", "author", "modelUsed", "tenantId", "number", "title", "content", "category", "authorId", "configurationItem", "summary", "id", "rootCause") VALUES ('1ac3e72d-3ec6-4e59-9034-09a93e7dc122', 'tenant_acme_01', 'KB0468207', 'SOP: High Memory Utilization on Control Plane of WorkerNode1HL', 'Run ps -eo pmem,pid,user,args | sort -nr | head to list top memory consuming processes. If memory utilization > 90%, proceed with escalation.', NULL, NULL, 'WorkerNode1HL', 'Standard Operating Procedure for handling High Memory Utilization telemetry alerts on Control Plane node WorkerNode1HL.', '["High Memory Utilization on Control Plane of WorkerNode1HL", "Memory utilization exceeded 90% threshold"]', 'High memory consumption by application or OS processes.', '["ssh root@192.168.100.101 ps -eo pmem,pid,user,args|sort -nr|head", "ssh root@192.168.100.101 if Memory utilization < 90, resolve ticket; else escalate to human"]', NULL, NULL, NULL, NULL, 0, 0, 5.0, TRUE, 1, '2026-08-07 01:30:01.274000', '2026-08-07 01:30:01.274000') ON CONFLICT DO NOTHING;
