INSERT INTO "Incident" ("updatedAt", "closedAt", "resolvedAt", "createdAt", "activitiesJson", "state", "impact", "urgency", "priority", "callerId", "callerName", "assignedToId", "id", "assignmentGroupId", "configurationItemId", "resolutionNotes", "department", "resolutionCode", "configurationItemName", "assignedToName", "tenantId", "number", "shortDescription", "description") VALUES ('9362832d-3754-4897-9f3c-4299f9ffe149', 'tenant_acme_01', 'INC1986190', 'High CPU on WorkerNode1HL', 'High CPU Utilization on Control Plane of WorkerNode1HL', 'ON_HOLD', 'TEAM', 'HIGH', 'HIGH', NULL, NULL, NULL, 'DevOps Team', NULL, NULL, NULL, NULL, 'High CPU on the Kubernetes control plane of WorkerNode1HL indicates a platform-level issue with control plane components (kube-apiserver, etcd, controller-manager). This requires DevOps expertise for cluster diagnostics, resource quota analysis, and potential control plane scaling or configuration tuning.', '2026-08-07 01:51:52.111000', '2026-08-07 01:55:23.960000', 'DevOps Ops', NULL, NULL, '[{"id": "act_1786067723926", "author": "\ud83e\udde0 AI Knowledge Synthesizer", "comment": "\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\ud83e\udde0 AI KNOWLEDGE SYNTHESIZER: NEW SOP SUBMITTED FOR APPROVAL\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\ud83d\udd0d RAG Search: Miss (No matching SOP found in local Vector DB).\n\ud83d\udcdd Action: Synthesized a new SOP and requested Human-in-the-Loop review.\n\ud83c\udfab Ticket: [INC1986190] High CPU on WorkerNode1HL\nProposed SOP Title: SOP: High CPU Utilization on Kubernetes Control Plane Node\nProposed Commands: ssh root@192.168.100.101 \"top -bn1 | head -20\", ssh root@192.168.100.101 \"mpstat -P ALL 1 3\", ssh root@192.168.100.101 \"ps aux --sort=-%cpu | head -20\", ssh root@192.168.100.101 \"pidstat -u -p ALL 1 3 | grep -E ''(kube|etcd|containerd|crio|docker)''\", ssh root@192.168.100.101 \"systemctl list-units --type=service --state=running | grep -E ''(kube|etcd|containerd|crio)''\", ssh root@192.168.100.101 \"for svc in kube-apiserver kube-controller-manager kube-scheduler etcd containerd crio docker kubelet; do systemctl status $svc --no-pager 2>/dev/null | head -30; done\", ssh root@192.168.100.101 \"journalctl -u kube-apiserver --since ''30 min ago'' --no-pager | tail -100\", ssh root@192.168.100.101 \"journalctl -u kube-controller-manager --since ''30 min ago'' --no-pager | tail -100\", ssh root@192.168.100.101 \"journalctl -u kube-scheduler --since ''30 min ago'' --no-pager | tail -100\", ssh root@192.168.100.101 \"journalctl -u etcd --since ''30 min ago'' --no-pager | tail -100\", ssh root@192.168.100.101 \"ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key endpoint status --write-out=table\", ssh root@192.168.100.101 \"ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key endpoint health --write-out=table\", ssh root@192.168.100.101 \"ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key alarm list\", ssh root@192.168.100.101 \"du -sh /var/lib/etcd 2>/dev/null || du -sh /var/lib/etcd/member 2>/dev/null\", ssh root@192.168.100.101 \"ls -lh /var/log/containers/ 2>/dev/null | head -20\", ssh root@192.168.100.101 \"ls -lh /var/log/pods/ 2>/dev/null | head -20\", ssh root@192.168.100.101 \"crictl stats --no-stream 2>/dev/null | sort -k3 -nr | head -20\", ssh root@192.168.100.101 \"grep -r ''audit'' /etc/kubernetes/manifests/kube-apiserver.yaml 2>/dev/null || echo ''Audit config not found in static pod manifest''\", ssh root@192.168.100.101 \"systemctl restart kube-apiserver && sleep 10 && systemctl status kube-apiserver --no-pager\", ssh root@192.168.100.101 \"systemctl restart kube-controller-manager && sleep 10 && systemctl status kube-controller-manager --no-pager\", ssh root@192.168.100.101 \"systemctl restart kube-scheduler && sleep 10 && systemctl status kube-scheduler --no-pager\", ssh root@192.168.100.101 \"ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key compact $(ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key endpoint status --write-out=json | jq -r ''.[0].Status.header.revision'') 2>/dev/null && ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key defrag\", ssh root@192.168.100.101 \"top -bn1 | head -10\", ssh root@192.168.100.101 \"kubectl get nodes -o wide 2>/dev/null || echo ''kubectl not available on control plane; run from bastion''\", ssh root@192.168.100.101 \"kubectl get componentstatuses 2>/dev/null || echo ''componentstatuses deprecated; check kube-apiserver healthz''\"\nState: Incident placed ON_HOLD awaiting human operator approval in Control Tower.\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501", "timestamp": "7:55:23 pm"}, {"id": "act_1786067625246", "author": "\ud83e\udd16 Agentic AI Router", "comment": "\ud83e\udd16 Agentic AI Router (NVIDIA Nemotron 3 550B LLM): Auto-assigned ticket to \"DevOps Ops\" (Alex Chen) with 85% confidence.\nReasoning: High CPU on the Kubernetes control plane of WorkerNode1HL indicates a platform-level issue with control plane components (kube-apiserver, etcd, controller-manager). This requires DevOps expertise for cluster diagnostics, resource quota analysis, and potential control plane scaling or configuration tuning.", "timestamp": "7:53:45 pm", "isWorkNote": true}]') ON CONFLICT DO NOTHING;
