INSERT INTO "Incident" ("updatedAt", "closedAt", "resolvedAt", "createdAt", "activitiesJson", "state", "impact", "urgency", "priority", "callerId", "callerName", "assignedToId", "id", "assignmentGroupId", "configurationItemId", "resolutionNotes", "department", "resolutionCode", "configurationItemName", "assignedToName", "tenantId", "number", "shortDescription", "description") VALUES ('dfab8a7c-cdb4-47f2-9210-82cc3d7c7bd9', 'tenant_acme_01', 'INC0001021', 'High COU Utilization on Control plane', 'High COU Utilization on Control plane', 'ON_HOLD', 'DEPARTMENT', 'HIGH', 'P2', NULL, 'System Admin', NULL, 'DevOps Team', NULL, NULL, NULL, NULL, 'The incident reports high CPU utilization on a control plane, which is specific terminology for container orchestration platforms (Kubernetes/OpenShift). This infrastructure component is managed by the DevOps/Platform Engineering team responsible for cluster control plane health, etcd performance, and API server scaling.', '2026-08-04 19:10:47.053000', '2026-08-04 19:13:58.431000', 'DevOps Ops', 'Pending Triage', 'Unspecified CI', '[{"id": "act_1785870838398", "author": "\ud83e\udde0 AI Knowledge Synthesizer", "comment": "\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\ud83e\udde0 AI KNOWLEDGE SYNTHESIZER: NEW SOP SUBMITTED FOR APPROVAL\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\ud83d\udd0d RAG Search: Miss (No matching SOP found in local Vector DB).\n\ud83d\udcdd Action: Synthesized a new SOP and requested Human-in-the-Loop review.\n\ud83c\udfab Ticket: [INC0001021] High COU Utilization on Control plane\nProposed SOP Title: SOP: High CPU Utilization on Kubernetes Control Plane Node\nProposed Commands: ssh root@192.168.100.101 \"ps aux --sort=-%cpu | head -20\", ssh root@192.168.100.101 \"top -b -n1 | head -30\", ssh root@192.168.100.101 \"systemctl status kubelet kube-apiserver kube-controller-manager kube-scheduler etcd --no-pager\", ssh root@192.168.100.101 \"journalctl -u kube-apiserver -u kube-controller-manager -u kube-scheduler -u etcd --since \"30 minutes ago\" --no-pager | grep -E -i \"error|warn|fail|panic|oom|throttl\" | head -50\", ssh root@192.168.100.101 \"kubectl get --raw /metrics 2>/dev/null | grep -E ''apiserver_request_duration_seconds|apiserver_request_total|process_cpu_seconds_total'' | head -30\", ssh root@192.168.100.101 \"crictl stats --no-stream 2>/dev/null | sort -k3 -nr | head -10\", ssh root@192.168.100.101 \"ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key endpoint status -w table 2>/dev/null\", ssh root@192.168.100.101 \"grep -c \"requestURI\" /var/log/kubernetes/audit.log 2>/dev/null || echo \"Audit log not found or not accessible\"\", ssh root@192.168.100.101 \"TOP_PROCESS=$(ps aux --sort=-%cpu | awk ''NR==2 {print $11}''); if [[ \"$TOP_PROCESS\" == *\"kube-apiserver\"* ]]; then echo \"kube-apiserver is top CPU consumer, restarting...\"; systemctl restart kube-apiserver && sleep 10 && systemctl status kube-apiserver --no-pager; fi\", ssh root@192.168.100.101 \"TOP_PROCESS=$(ps aux --sort=-%cpu | awk ''NR==2 {print $11}''); if [[ \"$TOP_PROCESS\" == *\"kube-controller-manager\"* ]]; then echo \"kube-controller-manager is top CPU consumer, restarting...\"; systemctl restart kube-controller-manager && sleep 10 && systemctl status kube-controller-manager --no-pager; fi\", ssh root@192.168.100.101 \"TOP_PROCESS=$(ps aux --sort=-%cpu | awk ''NR==2 {print $11}''); if [[ \"$TOP_PROCESS\" == *\"etcd\"* ]]; then echo \"etcd is top CPU consumer, attempting compaction and restart...\"; REV=$(ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key endpoint status --write-out=fields 2>/dev/null | grep Revision | awk ''{print $2}''); if [ -n \"$REV\" ]; then ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key compact \"$REV\" 2>/dev/null; fi; systemctl restart etcd && sleep 15 && systemctl status etcd --no-pager; fi\", ssh root@192.168.100.101 \"ps aux --sort=-%cpu | head -10\", ssh root@192.168.100.101 \"uptime\"\nState: Incident placed ON_HOLD awaiting human operator approval in Control Tower.\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501", "timestamp": "1:13:58 PM"}, {"id": "act_1785870666991", "author": "\ud83e\udd16 Agentic AI Router", "comment": "\ud83e\udd16 Agentic AI Router (NVIDIA Nemotron 3 550B LLM): Auto-assigned ticket to \"DevOps Ops\" (Marcus Chen) with 90% confidence.\nReasoning: The incident reports high CPU utilization on a control plane, which is specific terminology for container orchestration platforms (Kubernetes/OpenShift). This infrastructure component is managed by the DevOps/Platform Engineering team responsible for cluster control plane health, etcd performance, and API server scaling.", "timestamp": "1:11:06 PM", "isWorkNote": true}, {"id": "act_INC0001021_1", "author": "System Admin", "comment": "Logged new incident ticket INC0001021.", "timestamp": "1:10:47 PM", "isWorkNote": true}]') ON CONFLICT DO NOTHING;
