INSERT INTO "AgentApproval" ("confidenceScore", "timestamp", "details", "entityType", "summary", "id", "status", "proposedAction", "type", "entityId") VALUES ('APPR-3527', 'EXECUTION', 'fc6415ac-e5b2-4526-a978-91931386c36d', 'Incident', 'This SOP addresses high memory utilization on the Kubernetes control plane node (192.168.100.101). The failure mode typically involves memory pressure on critical control plane components (kube-apiserver, etcd, controller-manager, scheduler) or container runtime overhead, risking API instability or node eviction. The resolution identifies top memory consumers, analyzes container vs process memory, and applies targeted remediation such as restarting leaky components or clearing slab/cache safely.', 'Execute SSH Remediation', 85.0, 'REJECTED', '2026-08-07 01:38:53.579000', '{"model": "nvidia/nemotron-3-ultra-550b-a55b", "kbTitle": "SOP: High Memory Utilization on Kubernetes Control Plane Node (WorkerNode1HL)", "summary": "This SOP addresses high memory utilization on the Kubernetes control plane node (192.168.100.101). The failure mode typically involves memory pressure on critical control plane components (kube-apiserver, etcd, controller-manager, scheduler) or container runtime overhead, risking API instability or node eviction. The resolution identifies top memory consumers, analyzes container vs process memory, and applies targeted remediation such as restarting leaky components or clearing slab/cache safely.", "targetCi": "control plane (192.168.100.101)", "riskLevel": "HIGH", "department": "DevOps Team", "aiReasoning": "High memory on a control plane node threatens cluster stability. The steps progress from system-wide memory analysis (free, meminfo) to process-level (ps) and container-level (crictl/docker stats) inspection. Control plane components often run as static pods; checking systemd units and manifest resource limits identifies misconfigurations. Slab memory (slabtop) reveals kernel cache pressure. Dropping caches (drop_caches) is safe and non-disruptive. Restarting kubelet triggers static pod recreation, effectively restarting control plane components with fresh memory state. Safety checks validate API server, etcd, kubelet, and node readiness post-remediation. No external dependencies or hallucinated URLs used; all commands are standard Linux/Kubernetes tooling.", "safetyChecks": [{"check": "Verify API server responsiveness: curl -k --max-time 5 https://192.168.100.101:6443/healthz 2>/dev/null | grep -q ''ok'' && echo ''API server healthy'' || echo ''API server UNHEALTHY - escalate immediately''", "passed": true}, {"check": "Verify etcd cluster health: ETCDCTL_API=3 etcdctl --endpoints=https://192.168.100.101:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/peer.crt --key=/etc/kubernetes/pki/etcd/peer.key endpoint health 2>/dev/null | grep -q ''healthy'' && echo ''etcd healthy'' || echo ''etcd UNHEALTHY - escalate immediately''", "passed": true}, {"check": "Confirm kubelet is active: systemctl is-active kubelet | grep -q ''^active$'' && echo ''kubelet active'' || echo ''kubelet INACTIVE - escalate immediately''", "passed": true}, {"check": "Check node Ready status from another control plane node: kubectl get node workernode1hl -o jsonpath=''{.status.conditions[?(@.type==\"Ready\")].status}'' 2>/dev/null | grep -q ''True'' && echo ''Node Ready'' || echo ''Node NotReady - investigate further''", "passed": true}, {"check": "Ensure no OOM kills in last hour: dmesg -T | grep -i ''out of memory'' | tail -5 || echo ''No recent OOM kills detected''", "passed": true}], "incidentTitle": "High Memory on WorkerNode1HL", "confidenceScore": 85, "rejectionReason": "skipping", "proposedCommands": ["ssh root@192.168.100.101 \"free -h && echo ''---'' && cat /proc/meminfo | grep -E ''MemTotal|MemFree|MemAvailable|Buffers|Cached|SwapTotal|SwapFree|Active|Inactive|Slab|SReclaimable|SUnreclaim''\"", "ssh root@192.168.100.101 \"ps aux --sort=-%mem | head -n 20\"", "ssh root@192.168.100.101 \"systemctl status kubelet containerd crio docker 2>/dev/null | grep -E ''^\\s*(Active|Memory|Tasks|CGroup)'' || true\"", "ssh root@192.168.100.101 \"crictl ps -a 2>/dev/null || docker ps -a 2>/dev/null || echo ''Container runtime CLI not found or no containers''\"", "ssh root@192.168.100.101 \"crictl stats --no-stream 2>/dev/null | sort -k3 -hr | head -n 15 || docker stats --no-stream 2>/dev/null | sort -k3 -hr | head -n 15 || true\"", "ssh root@192.168.100.101 \"for svc in kube-apiserver kube-controller-manager kube-scheduler etcd; do systemctl status $svc 2>/dev/null | grep -E ''^(Active|Memory|MainPID)'' || echo \"$svc: not managed by systemd (static pod?)\"; done\"", "ssh root@192.168.100.101 \"grep -r ''memory'' /etc/kubernetes/manifests/ 2>/dev/null | grep -v ''^#'' | head -n 20 || echo ''No static pod memory limits found in manifests''\"", "ssh root@192.168.100.101 \"slabtop -o -s c | head -n 30 2>/dev/null || echo ''slabtop not available, checking /proc/slabinfo'' && cat /proc/slabinfo | sort -k3 -nr | head -n 20\"", "ssh root@192.168.100.101 \"sync && echo 3 > /proc/sys/vm/drop_caches && echo ''Pagecache, dentries, and inodes dropped''\"", "ssh root@192.168.100.101 \"systemctl restart kubelet 2>/dev/null && echo ''kubelet restarted'' || echo ''kubelet restart skipped or failed''\"", "ssh root@192.168.100.101 \"for pod in kube-apiserver kube-controller-manager kube-scheduler etcd; do crictl stop -t 30 $(crictl pods --name $pod -q 2>/dev/null | head -n1) 2>/dev/null && crictl rmp $(crictl pods --name $pod -q 2>/dev/null | head -n1) 2>/dev/null && echo \"$pod static pod recreated by kubelet\" || echo \"$pod: no action taken\"; sleep 2; done\"", "ssh root@192.168.100.101 \"free -h && echo ''---'' && ps aux --sort=-%mem | head -n 10\"", "ssh root@192.168.100.101 \"crictl stats --no-stream 2>/dev/null | sort -k3 -hr | head -n 10 || docker stats --no-stream 2>/dev/null | sort -k3 -hr | head -n 10 || true\""], "synthesizerOutput": {"kbTitle": "SOP: High Memory Utilization on Kubernetes Control Plane Node (WorkerNode1HL)", "draftKbId": "KB-SOP-NEW", "trendInsight": "Synthesized SOP containing 13 resolution steps starting with SSH connection.", "resolutionSteps": ["ssh root@192.168.100.101 \"free -h && echo ''---'' && cat /proc/meminfo | grep -E ''MemTotal|MemFree|MemAvailable|Buffers|Cached|SwapTotal|SwapFree|Active|Inactive|Slab|SReclaimable|SUnreclaim''\"", "ssh root@192.168.100.101 \"ps aux --sort=-%mem | head -n 20\"", "ssh root@192.168.100.101 \"systemctl status kubelet containerd crio docker 2>/dev/null | grep -E ''^\\s*(Active|Memory|Tasks|CGroup)'' || true\"", "ssh root@192.168.100.101 \"crictl ps -a 2>/dev/null || docker ps -a 2>/dev/null || echo ''Container runtime CLI not found or no containers''\"", "ssh root@192.168.100.101 \"crictl stats --no-stream 2>/dev/null | sort -k3 -hr | head -n 15 || docker stats --no-stream 2>/dev/null | sort -k3 -hr | head -n 15 || true\"", "ssh root@192.168.100.101 \"for svc in kube-apiserver kube-controller-manager kube-scheduler etcd; do systemctl status $svc 2>/dev/null | grep -E ''^(Active|Memory|MainPID)'' || echo \"$svc: not managed by systemd (static pod?)\"; done\"", "ssh root@192.168.100.101 \"grep -r ''memory'' /etc/kubernetes/manifests/ 2>/dev/null | grep -v ''^#'' | head -n 20 || echo ''No static pod memory limits found in manifests''\"", "ssh root@192.168.100.101 \"slabtop -o -s c | head -n 30 2>/dev/null || echo ''slabtop not available, checking /proc/slabinfo'' && cat /proc/slabinfo | sort -k3 -nr | head -n 20\"", "ssh root@192.168.100.101 \"sync && echo 3 > /proc/sys/vm/drop_caches && echo ''Pagecache, dentries, and inodes dropped''\"", "ssh root@192.168.100.101 \"systemctl restart kubelet 2>/dev/null && echo ''kubelet restarted'' || echo ''kubelet restart skipped or failed''\"", "ssh root@192.168.100.101 \"for pod in kube-apiserver kube-controller-manager kube-scheduler etcd; do crictl stop -t 30 $(crictl pods --name $pod -q 2>/dev/null | head -n1) 2>/dev/null && crictl rmp $(crictl pods --name $pod -q 2>/dev/null | head -n1) 2>/dev/null && echo \"$pod static pod recreated by kubelet\" || echo \"$pod: no action taken\"; sleep 2; done\"", "ssh root@192.168.100.101 \"free -h && echo ''---'' && ps aux --sort=-%mem | head -n 10\"", "ssh root@192.168.100.101 \"crictl stats --no-stream 2>/dev/null | sort -k3 -hr | head -n 10 || docker stats --no-stream 2>/dev/null | sort -k3 -hr | head -n 10 || true\""], "synthesizedSolution": "ssh root@192.168.100.101 \"free -h && echo ''---'' && cat /proc/meminfo | grep -E ''MemTotal|MemFree|MemAvailable|Buffers|Cached|SwapTotal|SwapFree|Active|Inactive|Slab|SReclaimable|SUnreclaim''\"\nssh root@192.168.100.101 \"ps aux --sort=-%mem | head -n 20\"\nssh root@192.168.100.101 \"systemctl status kubelet containerd crio docker 2>/dev/null | grep -E ''^\\s*(Active|Memory|Tasks|CGroup)'' || true\"\nssh root@192.168.100.101 \"crictl ps -a 2>/dev/null || docker ps -a 2>/dev/null || echo ''Container runtime CLI not found or no containers''\"\nssh root@192.168.100.101 \"crictl stats --no-stream 2>/dev/null | sort -k3 -hr | head -n 15 || docker stats --no-stream 2>/dev/null | sort -k3 -hr | head -n 15 || true\"\nssh root@192.168.100.101 \"for svc in kube-apiserver kube-controller-manager kube-scheduler etcd; do systemctl status $svc 2>/dev/null | grep -E ''^(Active|Memory|MainPID)'' || echo \"$svc: not managed by systemd (static pod?)\"; done\"\nssh root@192.168.100.101 \"grep -r ''memory'' /etc/kubernetes/manifests/ 2>/dev/null | grep -v ''^#'' | head -n 20 || echo ''No static pod memory limits found in manifests''\"\nssh root@192.168.100.101 \"slabtop -o -s c | head -n 30 2>/dev/null || echo ''slabtop not available, checking /proc/slabinfo'' && cat /proc/slabinfo | sort -k3 -nr | head -n 20\"\nssh root@192.168.100.101 \"sync && echo 3 > /proc/sys/vm/drop_caches && echo ''Pagecache, dentries, and inodes dropped''\"\nssh root@192.168.100.101 \"systemctl restart kubelet 2>/dev/null && echo ''kubelet restarted'' || echo ''kubelet restart skipped or failed''\"\nssh root@192.168.100.101 \"for pod in kube-apiserver kube-controller-manager kube-scheduler etcd; do crictl stop -t 30 $(crictl pods --name $pod -q 2>/dev/null | head -n1) 2>/dev/null && crictl rmp $(crictl pods --name $pod -q 2>/dev/null | head -n1) 2>/dev/null && echo \"$pod static pod recreated by kubelet\" || echo \"$pod: no action taken\"; sleep 2; done\"\nssh root@192.168.100.101 \"free -h && echo ''---'' && ps aux --sort=-%mem | head -n 10\"\nssh root@192.168.100.101 \"crictl stats --no-stream 2>/dev/null | sort -k3 -hr | head -n 10 || docker stats --no-stream 2>/dev/null | sort -k3 -hr | head -n 10 || true\""}, "kbArticleReference": "KB_NEW"}') ON CONFLICT DO NOTHING;
INSERT INTO "AgentApproval" ("confidenceScore", "timestamp", "details", "entityType", "summary", "id", "status", "proposedAction", "type", "entityId") VALUES ('APPR-4375', 'EXECUTION', '2553f784-8b0c-4e53-9170-4d1f98bae5b8', 'Incident', 'High CPU on control plane nodes typically stems from kube-apiserver request storms (e.g., watch leaks, misconfigured informers), etcd compaction/defrag cycles, or runaway controller-manager reconciliation loops. This SOP isolates the offending process via PID mapping, validates etcd health, and applies targeted mitigation (restart of specific static pod) without full node reboot.', 'Execute SSH Remediation', 85.0, 'REJECTED', '2026-08-07 00:10:42.664000', '{"model": "nvidia/nemotron-3-ultra-550b-a55b", "kbTitle": "SOP: High CPU Utilization on Kubernetes Control Plane Node", "summary": "High CPU on control plane nodes typically stems from kube-apiserver request storms (e.g., watch leaks, misconfigured informers), etcd compaction/defrag cycles, or runaway controller-manager reconciliation loops. This SOP isolates the offending process via PID mapping, validates etcd health, and applies targeted mitigation (restart of specific static pod) without full node reboot.", "targetCi": "Control Plane (192.168.100.101)", "riskLevel": "HIGH", "department": "DevOps Team", "aiReasoning": "Control plane CPU spikes are rarely generic; they map to specific components. Step 1-4 identify the PID/container consuming CPU. Steps 5-6 map PIDs to component names and check kubelet/journal for OOM kills or throttling. Steps 7-8 inspect component logs for watch leaks, audit webhook timeouts, or etcd slow applies. Steps 9-10 verify etcd quorum and alarms (critical before restarts). Step 11 confirms kubelet health. Step 12 checks if static pods lack CPU limits (common root cause). Step 13 shows per-container usage. Steps 14-16 perform graceful restarts of offending static pods via crictl (kubelet will restart them immediately with same spec). Step 17 validates mitigation. Step 18 confirms all control plane pods are Running. Restarting via crictl is safer than systemctl restart kubelet (which cycles all pods).", "safetyChecks": [{"check": "Verify etcd cluster health (endpoint status) before restarting any control plane component to avoid quorum loss", "passed": true}, {"check": "Confirm kubelet is running and managing static pods before issuing crictl stop commands", "passed": true}, {"check": "Ensure no active leadership elections are disrupted (check logs for ''leader elected'' messages post-restart)", "passed": true}, {"check": "Validate API server responsiveness post-restart: ''kubectl get nodes --request-timeout=5s'' from a healthy node or local admin kubeconfig", "passed": true}, {"check": "Check CPU returns to baseline (< 70% sustained) for 10 minutes before closing ticket", "passed": true}], "incidentTitle": "High CPU Utilization on Control Plane", "confidenceScore": 85, "rejectionReason": "skipping", "proposedCommands": ["ssh root@192.168.100.101 \"top -b -n 1 | head -20\"", "ssh root@192.168.100.101 \"ps aux --sort=-%cpu | head -15\"", "ssh root@192.168.100.101 \"crictl ps --sort-by cpu --no-trunc | head -20\"", "ssh root@192.168.100.101 \"crictl top | head -20\"", "ssh root@192.168.100.101 \"for pid in $(pgrep -f ''kube-apiserver|kube-controller-manager|kube-scheduler|etcd''); do echo \"--- PID $pid ---\"; cat /proc/$pid/cmdline | xargs -0 echo; done\"", "ssh root@192.168.100.101 \"journalctl -u kubelet --since ''30 min ago'' -p err..crit --no-pager | tail -30\"", "ssh root@192.168.100.101 \"crictl logs $(crictl ps --name kube-apiserver -q) --tail=100 2>/dev/null | grep -E ''WARN|ERROR|panic|throttle'' | tail -20\"", "ssh root@192.168.100.101 \"crictl logs $(crictl ps --name etcd -q) --tail=100 2>/dev/null | grep -E ''apply took|slow|compaction|defrag'' | tail -10\"", "ssh root@192.168.100.101 \"etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key endpoint status --write-out=table\"", "ssh root@192.168.100.101 \"etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key alarm list\"", "ssh root@192.168.100.101 \"if systemctl is-active --quiet kubelet; then echo ''Kubelet active''; else systemctl status kubelet --no-pager; fi\"", "ssh root@192.168.100.101 \"grep -r ''requests\\|limits'' /etc/kubernetes/manifests/ 2>/dev/null | grep -v ''^#'' || echo ''No resource limits defined in static pod manifests''\"", "ssh root@192.168.100.101 \"crictl stats --no-stream 2>/dev/null | awk ''NR>1 {print $1,$2,$3,$4}'' | sort -k3 -nr | head -10\"", "ssh root@192.168.100.101 \"if pgrep -f ''kube-apiserver'' >/dev/null; then crictl stop -t 30 $(crictl ps --name kube-apiserver -q) && sleep 5 && crictl ps --name kube-apiserver; fi\"", "ssh root@192.168.100.101 \"if pgrep -f ''kube-controller-manager'' >/dev/null; then crictl stop -t 30 $(crictl ps --name kube-controller-manager -q) && sleep 5 && crictl ps --name kube-controller-manager; fi\"", "ssh root@192.168.100.101 \"if pgrep -f ''kube-scheduler'' >/dev/null; then crictl stop -t 30 $(crictl ps --name kube-scheduler -q) && sleep 5 && crictl ps --name kube-scheduler; fi\"", "ssh root@192.168.100.101 \"sleep 30 && top -b -n 1 | head -10\"", "ssh root@192.168.100.101 \"crictl ps --name kube-apiserver --name kube-controller-manager --name kube-scheduler --name etcd --no-trunc\""], "synthesizerOutput": {"kbTitle": "SOP: High CPU Utilization on Kubernetes Control Plane Node", "draftKbId": "KB-SOP-NEW", "trendInsight": "Synthesized SOP containing 18 resolution steps starting with SSH connection.", "resolutionSteps": ["ssh root@192.168.100.101 \"top -b -n 1 | head -20\"", "ssh root@192.168.100.101 \"ps aux --sort=-%cpu | head -15\"", "ssh root@192.168.100.101 \"crictl ps --sort-by cpu --no-trunc | head -20\"", "ssh root@192.168.100.101 \"crictl top | head -20\"", "ssh root@192.168.100.101 \"for pid in $(pgrep -f ''kube-apiserver|kube-controller-manager|kube-scheduler|etcd''); do echo \"--- PID $pid ---\"; cat /proc/$pid/cmdline | xargs -0 echo; done\"", "ssh root@192.168.100.101 \"journalctl -u kubelet --since ''30 min ago'' -p err..crit --no-pager | tail -30\"", "ssh root@192.168.100.101 \"crictl logs $(crictl ps --name kube-apiserver -q) --tail=100 2>/dev/null | grep -E ''WARN|ERROR|panic|throttle'' | tail -20\"", "ssh root@192.168.100.101 \"crictl logs $(crictl ps --name etcd -q) --tail=100 2>/dev/null | grep -E ''apply took|slow|compaction|defrag'' | tail -10\"", "ssh root@192.168.100.101 \"etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key endpoint status --write-out=table\"", "ssh root@192.168.100.101 \"etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key alarm list\"", "ssh root@192.168.100.101 \"if systemctl is-active --quiet kubelet; then echo ''Kubelet active''; else systemctl status kubelet --no-pager; fi\"", "ssh root@192.168.100.101 \"grep -r ''requests\\|limits'' /etc/kubernetes/manifests/ 2>/dev/null | grep -v ''^#'' || echo ''No resource limits defined in static pod manifests''\"", "ssh root@192.168.100.101 \"crictl stats --no-stream 2>/dev/null | awk ''NR>1 {print $1,$2,$3,$4}'' | sort -k3 -nr | head -10\"", "ssh root@192.168.100.101 \"if pgrep -f ''kube-apiserver'' >/dev/null; then crictl stop -t 30 $(crictl ps --name kube-apiserver -q) && sleep 5 && crictl ps --name kube-apiserver; fi\"", "ssh root@192.168.100.101 \"if pgrep -f ''kube-controller-manager'' >/dev/null; then crictl stop -t 30 $(crictl ps --name kube-controller-manager -q) && sleep 5 && crictl ps --name kube-controller-manager; fi\"", "ssh root@192.168.100.101 \"if pgrep -f ''kube-scheduler'' >/dev/null; then crictl stop -t 30 $(crictl ps --name kube-scheduler -q) && sleep 5 && crictl ps --name kube-scheduler; fi\"", "ssh root@192.168.100.101 \"sleep 30 && top -b -n 1 | head -10\"", "ssh root@192.168.100.101 \"crictl ps --name kube-apiserver --name kube-controller-manager --name kube-scheduler --name etcd --no-trunc\""], "synthesizedSolution": "ssh root@192.168.100.101 \"top -b -n 1 | head -20\"\nssh root@192.168.100.101 \"ps aux --sort=-%cpu | head -15\"\nssh root@192.168.100.101 \"crictl ps --sort-by cpu --no-trunc | head -20\"\nssh root@192.168.100.101 \"crictl top | head -20\"\nssh root@192.168.100.101 \"for pid in $(pgrep -f ''kube-apiserver|kube-controller-manager|kube-scheduler|etcd''); do echo \"--- PID $pid ---\"; cat /proc/$pid/cmdline | xargs -0 echo; done\"\nssh root@192.168.100.101 \"journalctl -u kubelet --since ''30 min ago'' -p err..crit --no-pager | tail -30\"\nssh root@192.168.100.101 \"crictl logs $(crictl ps --name kube-apiserver -q) --tail=100 2>/dev/null | grep -E ''WARN|ERROR|panic|throttle'' | tail -20\"\nssh root@192.168.100.101 \"crictl logs $(crictl ps --name etcd -q) --tail=100 2>/dev/null | grep -E ''apply took|slow|compaction|defrag'' | tail -10\"\nssh root@192.168.100.101 \"etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key endpoint status --write-out=table\"\nssh root@192.168.100.101 \"etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key alarm list\"\nssh root@192.168.100.101 \"if systemctl is-active --quiet kubelet; then echo ''Kubelet active''; else systemctl status kubelet --no-pager; fi\"\nssh root@192.168.100.101 \"grep -r ''requests\\|limits'' /etc/kubernetes/manifests/ 2>/dev/null | grep -v ''^#'' || echo ''No resource limits defined in static pod manifests''\"\nssh root@192.168.100.101 \"crictl stats --no-stream 2>/dev/null | awk ''NR>1 {print $1,$2,$3,$4}'' | sort -k3 -nr | head -10\"\nssh root@192.168.100.101 \"if pgrep -f ''kube-apiserver'' >/dev/null; then crictl stop -t 30 $(crictl ps --name kube-apiserver -q) && sleep 5 && crictl ps --name kube-apiserver; fi\"\nssh root@192.168.100.101 \"if pgrep -f ''kube-controller-manager'' >/dev/null; then crictl stop -t 30 $(crictl ps --name kube-controller-manager -q) && sleep 5 && crictl ps --name kube-controller-manager; fi\"\nssh root@192.168.100.101 \"if pgrep -f ''kube-scheduler'' >/dev/null; then crictl stop -t 30 $(crictl ps --name kube-scheduler -q) && sleep 5 && crictl ps --name kube-scheduler; fi\"\nssh root@192.168.100.101 \"sleep 30 && top -b -n 1 | head -10\"\nssh root@192.168.100.101 \"crictl ps --name kube-apiserver --name kube-controller-manager --name kube-scheduler --name etcd --no-trunc\""}, "kbArticleReference": "KB_NEW"}') ON CONFLICT DO NOTHING;
INSERT INTO "AgentApproval" ("confidenceScore", "timestamp", "details", "entityType", "summary", "id", "status", "proposedAction", "type", "entityId") VALUES ('APPR-5319', 'EXECUTION', '53837363-97f7-4614-a902-def10aa578ca', 'Incident', 'The Nexacore web application on WorkerNode1HL (192.168.100.102) is refusing connections on TCP port 8080, indicating the application process is not listening. This SOP covers verification of the service state (systemd or container), inspection of logs for root cause, service restart, and validation of port binding and HTTP response.', 'Execute SSH Remediation', 85.0, 'REJECTED', '2026-08-07 18:33:01.312000', '{"model": "nvidia/nemotron-3-ultra-550b-a55b", "kbTitle": "SOP: Nexacore Website Connection Refused on Port 8080 - WorkerNode1HL", "summary": "The Nexacore web application on WorkerNode1HL (192.168.100.102) is refusing connections on TCP port 8080, indicating the application process is not listening. This SOP covers verification of the service state (systemd or container), inspection of logs for root cause, service restart, and validation of port binding and HTTP response.", "targetCi": "WorkerNode1HL (192.168.100.102)", "riskLevel": "HIGH", "department": "DevOps Team", "aiReasoning": "Connection refused on port 8080 indicates no process is bound to the port. The Nexacore application likely runs as a systemd service or container. First, identify the runtime (systemd vs Docker vs CRI-O). Check logs for crash reasons (OOM, config error, dependency failure). Restart the appropriate unit. Validate port binding and HTTP response. If containerized, ensure container networking and port mapping are correct. This procedure is idempotent and safe for production.", "safetyChecks": [{"check": "Verify port 8080 is in LISTEN state via ss or netstat after restart", "passed": true}, {"check": "Confirm HTTP 2xx/3xx response from local curl to /health or root endpoint", "passed": true}, {"check": "Ensure no duplicate service instances are running (systemd + container conflict)", "passed": true}, {"check": "Check systemd unit status: systemctl status nexacore --no-pager", "passed": true}], "incidentTitle": "Nexacore website is down on Workernode1HL on port 8080: connection refused. 192.168.100.102", "confidenceScore": 85, "proposedCommands": ["ssh root@192.168.100.102 \"systemctl list-units --type=service --state=active | grep -iE ''nexacore|web|app'' || echo ''No matching systemd services found''\"", "ssh root@192.168.100.102 \"ss -ltnp ''sport = :8080'' || netstat -ltnp 2>/dev/null | grep '':8080'' || echo ''Port 8080 not listening''\"", "ssh root@192.168.100.102 \"if command -v docker &>/dev/null; then docker ps --filter ''publish=8080'' --format ''table {{.Names}}\\t{{.Status}}\\t{{.Ports}}''; fi\"", "ssh root@192.168.100.102 \"if command -v crictl &>/dev/null; then crictl ps --label io.kubernetes.container.name=nexacore 2>/dev/null || crictl ps | grep 8080; fi\"", "ssh root@192.168.100.102 \"journalctl -u nexacore -n 100 --no-pager 2>/dev/null || journalctl -u nexacore.service -n 100 --no-pager 2>/dev/null || echo ''No systemd unit nexacore found''\"", "ssh root@192.168.100.102 \"if systemctl is-active --quiet nexacore 2>/dev/null; then systemctl restart nexacore; elif systemctl is-active --quiet nexacore.service 2>/dev/null; then systemctl restart nexacore.service; else echo ''Nexacore systemd service not found, checking for container...''; fi\"", "ssh root@192.168.100.102 \"if command -v docker &>/dev/null; then docker ps -a --filter ''name=nexacore'' --format ''{{.Names}}'' | xargs -r docker restart; fi\"", "ssh root@192.168.100.102 \"sleep 5\"", "ssh root@192.168.100.102 \"ss -ltnp ''sport = :8080'' || netstat -ltnp 2>/dev/null | grep '':8080''\""], "synthesizerOutput": {"kbTitle": "SOP: Nexacore Website Connection Refused on Port 8080 - WorkerNode1HL", "draftKbId": "KB-SOP-NEW", "trendInsight": "Synthesized SOP containing 9 resolution steps starting with SSH connection.", "resolutionSteps": ["ssh 