INSERT INTO "AgentApproval" ("confidenceScore", "timestamp", "details", "entityType", "summary", "id", "status", "proposedAction", "type", "entityId") VALUES ('APPR-4933', 'EXECUTION', 'a8b4af2a-3b2a-4453-b75a-61738189303f', 'Incident', 'This procedure details the secure deprovisioning of user ''siva'' from Workernode1HL (192.168.100.102). It archives the home directory for compliance, removes sudo privileges, deletes the account and home directory, and validates complete removal.', 'Execute SSH Remediation', 85.0, 'EXECUTED', '2026-08-05 09:52:34.882000', '{"model": "nvidia/nemotron-3-ultra-550b-a55b", "agentId": "agent-unix-resolver-01", "kbTitle": "SOP: Offboard User Account from Linux Worker Node", "targetCi": "WorkerNode1HL (192.168.100.102)", "agentName": "\ud83e\udd16 Unix Auto-Resolver Agent", "riskLevel": "HIGH", "approvedAt": "2026-08-05T09:52:35.208Z", "approvedBy": "Sarah Jenkins (Human in the Loop)", "department": "DevOps Team", "aiReasoning": "Offboarding requires audit-compliant data retention (tar archive), privilege revocation (sudoers.d removal), and complete account removal (userdel -r -f). The idempotent commands with ''|| true'' prevent pipeline failures if artifacts are already missing. Final ''id'' check provides definitive proof of deletion for ticket closure.", "safetyChecks": [{"check": "Verify target hostname matches Workernode1HL (192.168.100.102) before executing", "passed": true}, {"check": "Confirm user ''siva'' exists on target via ''id siva'' prior to deletion", "passed": true}, {"check": "Ensure archive file created in /root/ with current date suffix", "passed": true}, {"check": "Validate sudoers.d cleanup removed both possible filename patterns", "passed": true}, {"check": "Final validation confirms user no longer exists in /etc/passwd", "passed": true}], "incidentTitle": "offboard user siva from Workernode1HL", "proposedCommands": ["ssh root@192.168.100.102 \"tar -czf /root/siva_archive_$(date +%F).tar.gz -C /home siva 2>/dev/null || true\"", "ssh root@192.168.100.102 \"rm -f /etc/sudoers.d/siva /etc/sudoers.d/99-siva || true\"", "ssh root@192.168.100.102 \"userdel -r -f siva 2>/dev/null || true\"", "ssh root@192.168.100.102 \"id siva 2>/dev/null && echo ''User still exists'' || echo ''User successfully deleted''\""], "synthesizerOutput": {"kbTitle": "SOP: Offboard User Account from Linux Worker Node", "draftKbId": "KB-SOP-NEW", "trendInsight": "Synthesized SOP containing 4 resolution steps starting with SSH connection.", "resolutionSteps": ["ssh root@192.168.100.102 \"tar -czf /root/siva_archive_$(date +%F).tar.gz -C /home siva 2>/dev/null || true\"", "ssh root@192.168.100.102 \"rm -f /etc/sudoers.d/siva /etc/sudoers.d/99-siva || true\"", "ssh root@192.168.100.102 \"userdel -r -f siva 2>/dev/null || true\"", "ssh root@192.168.100.102 \"id siva 2>/dev/null && echo ''User still exists'' || echo ''User successfully deleted''\""], "synthesizedSolution": "ssh root@192.168.100.102 \"tar -czf /root/siva_archive_$(date +%F).tar.gz -C /home siva 2>/dev/null || true\"\nssh root@192.168.100.102 \"rm -f /etc/sudoers.d/siva /etc/sudoers.d/99-siva || true\"\nssh root@192.168.100.102 \"userdel -r -f siva 2>/dev/null || true\"\nssh root@192.168.100.102 \"id siva 2>/dev/null && echo ''User still exists'' || echo ''User successfully deleted''\""}, "kbArticleReference": "KB_NEW"}') ON CONFLICT DO NOTHING;
INSERT INTO "AgentApproval" ("confidenceScore", "timestamp", "details", "entityType", "summary", "id", "status", "proposedAction", "type", "entityId") VALUES ('APPR-3217', 'EXECUTION', '72039fff-da6d-4d25-9fbe-7e5275d10f40', 'Incident', 'Provisions a new local user ''Srinath'' on WorkerNode1HL (192.168.100.102) with passwordless sudo privileges. Uses idempotent user creation, secure SSH directory setup, and validated sudoers.d fragment to ensure compliance and auditability.', 'Execute SSH Remediation', 85.0, 'APPROVED', '2026-08-05 10:43:25.935000', '{"model": "nvidia/nemotron-3-ultra-550b-a55b", "agentId": "agent-unix-resolver-01", "kbTitle": "SOP: Create User Account with Sudo Access on WorkerNode1HL", "targetCi": "WorkerNode1HL (192.168.100.102)", "agentName": "\ud83e\udd16 Unix Auto-Resolver Agent", "riskLevel": "HIGH", "approvedAt": "2026-08-05T10:48:39.904Z", "approvedBy": "Sarah Jenkins (Human in the Loop)", "department": "DevOps Team", "aiReasoning": "Idempotent user creation prevents errors on re-runs. Using /etc/sudoers.d/ with visudo validation ensures syntax correctness and avoids locking out root. The .ssh directory is pre-created with strict permissions to allow immediate key-based authentication. All commands are self-contained and executable directly on the target host.", "safetyChecks": [{"check": "Verify sudoers syntax validation passed (visudo -c exit code 0)", "passed": true}, {"check": "Confirm user UID/GID and home directory ownership via ''id Srinath'' and ''ls -ld /home/Srinath''", "passed": true}, {"check": "Test passwordless sudo access: ''sudo -u Srinath sudo -n true'' (run as root)", "passed": true}], "incidentTitle": "Create user ID Srinath on Workernode1HL with sudo access.", "proposedCommands": ["ssh root@192.168.100.102 \"id -u Srinath &>/dev/null || useradd -m -s /bin/bash -c ''Srinath'' Srinath\"", "ssh root@192.168.100.102 \"mkdir -p /home/Srinath/.ssh && chmod 700 /home/Srinath/.ssh && chown -R Srinath:Srinath /home/Srinath/.ssh\"", "ssh root@192.168.100.102 \"echo ''Srinath ALL=(ALL) NOPASSWD:ALL'' > /etc/sudoers.d/99-Srinath && chmod 440 /etc/sudoers.d/99-Srinath && visudo -c -f /etc/sudoers.d/99-Srinath\"", "ssh root@192.168.100.102 \"id Srinath && ls -ld /home/Srinath\""], "synthesizerOutput": {"kbTitle": "SOP: Create User Account with Sudo Access on WorkerNode1HL", "draftKbId": "KB-SOP-NEW", "trendInsight": "Synthesized SOP containing 4 resolution steps starting with SSH connection.", "resolutionSteps": ["ssh root@192.168.100.102 \"id -u Srinath &>/dev/null || useradd -m -s /bin/bash -c ''Srinath'' Srinath\"", "ssh root@192.168.100.102 \"mkdir -p /home/Srinath/.ssh && chmod 700 /home/Srinath/.ssh && chown -R Srinath:Srinath /home/Srinath/.ssh\"", "ssh root@192.168.100.102 \"echo ''Srinath ALL=(ALL) NOPASSWD:ALL'' > /etc/sudoers.d/99-Srinath && chmod 440 /etc/sudoers.d/99-Srinath && visudo -c -f /etc/sudoers.d/99-Srinath\"", "ssh root@192.168.100.102 \"id Srinath && ls -ld /home/Srinath\""], "synthesizedSolution": "ssh root@192.168.100.102 \"id -u Srinath &>/dev/null || useradd -m -s /bin/bash -c ''Srinath'' Srinath\"\nssh root@192.168.100.102 \"mkdir -p /home/Srinath/.ssh && chmod 700 /home/Srinath/.ssh && chown -R Srinath:Srinath /home/Srinath/.ssh\"\nssh root@192.168.100.102 \"echo ''Srinath ALL=(ALL) NOPASSWD:ALL'' > /etc/sudoers.d/99-Srinath && chmod 440 /etc/sudoers.d/99-Srinath && visudo -c -f /etc/sudoers.d/99-Srinath\"\nssh root@192.168.100.102 \"id Srinath && ls -ld /home/Srinath\""}, "kbArticleReference": "KB_NEW"}') ON CONFLICT DO NOTHING;
INSERT INTO "AgentApproval" ("confidenceScore", "timestamp", "details", "entityType", "summary", "id", "status", "proposedAction", "type", "entityId") VALUES ('APPR-2135', 'EXECUTION', 'a05133fd-7c5f-4eb0-9a1f-49a0e987f3e0', 'Incident', 'Create OS user ''venu'' on the DB2 server for operating system authentication, grant CONNECT and DBADM authorities on TESTDB, and verify connectivity for CloudBeaver UI access. DB2 relies on OS-level users; provisioning a Linux account and assigning database privileges enables secure JDBC/ODBC connections from CloudBeaver.', 'Execute SSH Remediation', 85.0, 'REJECTED', '2026-08-07 06:09:06.717000', '{"model": "nvidia/nemotron-3-ultra-550b-a55b", "kbTitle": "SOP: Create IBM DB2 Database User with CloudBeaver Access", "summary": "Create OS user ''venu'' on the DB2 server for operating system authentication, grant CONNECT and DBADM authorities on TESTDB, and verify connectivity for CloudBeaver UI access. DB2 relies on OS-level users; provisioning a Linux account and assigning database privileges enables secure JDBC/ODBC connections from CloudBeaver.", "targetCi": "WorkerNode1HL (192.168.100.102)", "riskLevel": "HIGH", "department": "DevOps Team", "aiReasoning": "DB2 uses operating system authentication; creating a Linux user ''venu'' allows the DB2 instance to authenticate the user. Granting CONNECT permits database access, while DBADM provides administrative privileges required for schema management via CloudBeaver. Setting a temporary expired password enforces immediate rotation on first login, aligning with security policy. All commands are idempotent and validated locally on the target host.", "safetyChecks": [{"check": "Verify OS user exists: id venu returns UID/GID and home directory present", "passed": true}, {"check": "Verify DB2 grants: su - db2inst1 -c ''db2pd -db TESTDB -auth'' shows venu with CONNECT and DBADM", "passed": true}, {"check": "Test CloudBeaver connectivity: from CloudBeaver UI, create connection using hostname 192.168.100.102, port 50000, database TESTDB, user venu, password TempPass123! (force password change on first login)", "passed": true}], "incidentTitle": "Create IBM DB2 database user venu with CloudBeaver UI access", "confidenceScore": 85, "proposedCommands": ["ssh root@192.168.100.102 \"id -u venu &>/dev/null || useradd -m -s /bin/bash -c ''DB2 User Venu'' venu\"", "ssh root@192.168.100.102 \"mkdir -p /home/venu/.ssh && chmod 700 /home/venu/.ssh && chown -R venu:venu /home/venu/.ssh\"", "ssh root@192.168.100.102 \"echo ''venu:TempPass123!'' | chpasswd && chage -d 0 venu\"", "ssh root@192.168.100.102 \"id venu && ls -ld /home/venu\"", "ssh root@192.168.100.102 \"su - db2inst1 -c ''db2 connect to TESTDB''\"", "ssh root@192.168.100.102 \"su - db2inst1 -c ''db2 grant connect on database to user venu''\"", "ssh root@192.168.100.102 \"su - db2inst1 -c ''db2 grant dbadm on database to user venu''\"", "ssh root@192.168.100.102 \"su - db2inst1 -c ''db2 terminate''\"", "ssh root@192.168.100.102 \"su - db2inst1 -c ''db2 connect to TESTDB user venu using TempPass123!''\""], "synthesizerOutput": {"kbTitle": "SOP: Create IBM DB2 Database User with CloudBeaver Access", "draftKbId": "KB-SOP-NEW", "trendInsight": "Synthesized SOP containing 9 resolution steps starting with SSH connection.", "resolutionSteps": ["ssh root@192.168.100.102 \"id -u venu &>/dev/null || useradd -m -s /bin/bash -c ''DB2 User Venu'' venu\"", "ssh root@192.168.100.102 \"mkdir -p /home/venu/.ssh && chmod 700 /home/venu/.ssh && chown -R venu:venu /home/venu/.ssh\"", "ssh root@192.168.100.102 \"echo ''venu:TempPass123!'' | chpasswd && chage -d 0 venu\"", "ssh root@192.168.100.102 \"id venu && ls -ld /home/venu\"", "ssh root@192.168.100.102 \"su - db2inst1 -c ''db2 connect to TESTDB''\"", "ssh root@192.168.100.102 \"su - db2inst1 -c ''db2 grant connect on database to user venu''\"", "ssh root@192.168.100.102 \"su - db2inst1 -c ''db2 grant dbadm on database to user venu''\"", "ssh root@192.168.100.102 \"su - db2inst1 -c ''db2 terminate''\"", "ssh root@192.168.100.102 \"su - db2inst1 -c ''db2 connect to TESTDB user venu using TempPass123!''\""], "synthesizedSolution": "ssh root@192.168.100.102 \"id -u venu &>/dev/null || useradd -m -s /bin/bash -c ''DB2 User Venu'' venu\"\nssh root@192.168.100.102 \"mkdir -p /home/venu/.ssh && chmod 700 /home/venu/.ssh && chown -R venu:venu /home/venu/.ssh\"\nssh root@192.168.100.102 \"echo ''venu:TempPass123!'' | chpasswd && chage -d 0 venu\"\nssh root@192.168.100.102 \"id venu && ls -ld /home/venu\"\nssh root@192.168.100.102 \"su - db2inst1 -c ''db2 connect to TESTDB''\"\nssh root@192.168.100.102 \"su - db2inst1 -c ''db2 grant connect on database to user venu''\"\nssh root@192.168.100.102 \"su - db2inst1 -c ''db2 grant dbadm on database to user venu''\"\nssh root@192.168.100.102 \"su - db2inst1 -c ''db2 terminate''\"\nssh root@192.168.100.102 \"su - db2inst1 -c ''db2 connect to TESTDB user venu using TempPass123!''\""}, "kbArticleReference": "KB_NEW"}') ON CONFLICT DO NOTHING;
INSERT INTO "AgentApproval" ("confidenceScore", "timestamp", "details", "entityType", "summary", "id", "status", "proposedAction", "type", "entityId") VALUES ('APPR-9537', 'EXECUTION', 'a4463b3e-ac49-445f-bd4f-567e5f286d06', 'Incident', 'This SOP defines the standardized, auditable procedure for permanently removing a local user account from WorkerNode1HL (192.168.100.102). The process ensures data retention compliance via home directory archival, removes all privileged access vectors (sudoers), and validates complete account removal from the OS user database.', 'Execute SSH Remediation', 85.0, 'EXECUTED', '2026-08-05 11:49:32.942000', '{"model": "nvidia/nemotron-3-ultra-550b-a55b", "agentId": "agent-unix-resolver-01", "kbTitle": "SOP: User Account Deprovisioning - Offboarding Procedure for WorkerNode1HL", "targetCi": "WorkerNode1HL (192.168.100.102)", "agentName": "\ud83e\udd16 Unix Auto-Resolver Agent", "riskLevel": "HIGH", "approvedAt": "2026-08-05T11:49:44.213Z", "approvedBy": "Sarah Jenkins (Human in the Loop)", "department": "DevOps Team", "aiReasoning": "L2 Offboarding Standard: The procedure follows the principle of least surprise and audit compliance. Archival to /root (root-only access) preserves data for the retention period defined by policy before backup rotation. The ''|| true'' guards ensure idempotency if the user/home/sudoers are already absent, preventing script failure during automated runs. The final ''id'' check provides definitive proof of deletion for the ticket audit trail. The sudoers cleanup targets both possible naming conventions (username vs 99-username) to eliminate privilege escalation vectors.", "safetyChecks": [{"check": "Verify archive file exists and has non-zero size: ls -lh /root/Srinath_archive_$(date +%F).tar.gz", "passed": true}, {"check": "Confirm no residual sudoers entries: ls -l /etc/sudoers.d/ | grep -i srinath || echo ''No sudoers remnants found''", "passed": true}, {"check": "Validate UID/GID removal from /etc/passwd and /etc/group: grep -i srinath /etc/passwd /etc/group || echo ''No entries found in user/group databases''", "passed": true}], "incidentTitle": "User ID deletion for Srinath on WorkerNode1HL", "proposedCommands": ["ssh root@192.168.100.102 \"tar -czf /root/Srinath_archive_$(date +%F).tar.gz -C /home Srinath 2>/dev/null || true\"", "ssh root@192.168.100.102 \"rm -f /etc/sudoers.d/Srinath /etc/sudoers.d/99-Srinath || true\"", "ssh root@192.168.100.102 \"userdel -r -f Srinath 2>/dev/null || true\"", "ssh root@192.168.100.102 \"id Srinath 2>/dev/null && echo ''User still exists'' || echo ''User successfully deleted''\""], "synthesizerOutput": {"kbTitle": "SOP: User Account Deprovisioning - Offboarding Procedure for WorkerNode1HL", "draftKbId": "KB-SOP-NEW", "trendInsight": "Synthesized SOP containing 4 resolution steps starting with SSH connection.", "resolutionSteps": ["ssh root@192.168.100.102 \"tar -czf /root/Srinath_archive_$(date +%F).tar.gz -C /home Srinath 2>/dev/null || true\"", "ssh root@192.168.100.102 \"rm -f /etc/sudoers.d/Srinath /etc/sudoers.d/99-Srinath || true\"", "ssh root@192.168.100.102 \"userdel -r -f Srinath 2>/dev/null || true\"", "ssh root@192.168.100.102 \"id Srinath 2>/dev/null && echo ''User still exists'' || echo ''User successfully deleted''\""], "synthesizedSolution": "ssh root@192.168.100.102 \"tar -czf /root/Srinath_archive_$(date +%F).tar.gz -C /home Srinath 2>/dev/null || true\"\nssh root@192.168.100.102 \"rm -f /etc/sudoers.d/Srinath /etc/sudoers.d/99-Srinath || true\"\nssh root@192.168.100.102 \"userdel -r -f Srinath 2>/dev/null || true\"\nssh root@192.168.100.102 \"id Srinath 2>/dev/null && echo ''User still exists'' || echo ''User successfully deleted''\""}, "kbArticleReference": "KB_NEW"}') ON CONFLICT DO NOTHING;
INSERT INTO "AgentApproval" ("confidenceScore", "timestamp", "details", "entityType", "summary", "id", "status", "proposedAction", "type", "entityId") VALUES ('APPR-1748', 'EXECUTION', '50d6dbc0-6d49-4484-83df-4237803da53f', 'Incident', 'High CPU on a control plane node typically originates from etcd (compaction/defrag backlog), kube-apiserver (watch storms/audit logging), or kube-controller-manager (stuck reconcile loops). This SOP isolates the offending process via container runtime inspection, applies targeted remediation (etcd maintenance, component restart, config tuning), and validates stability.', 'Execute SSH Remediation', 85.0, 'REJECTED', '2026-08-07 00:14:18.541000', '{"model": "nvidia/nemotron-3-ultra-550b-a55b", "kbTitle": "SOP: High CPU Utilization Diagnosis & Remediation on Kubernetes Control Plane Node", "summary": "High CPU on a control plane node typically originates from etcd (compaction/defrag backlog), kube-apiserver (watch storms/audit logging), or kube-controller-manager (stuck reconcile loops). This SOP isolates the offending process via container runtime inspection, applies targeted remediation (etcd maintenance, component restart, config tuning), and validates stability.", "targetCi": "Control Plane (192.168.100.101)", "riskLevel": "HIGH", "department": "DevOps Team", "aiReasoning": "Control plane CPU spikes are rarely generic; they map to specific component pathologies. Etcd grows unbounded without compaction causing high CPU during WAL writes/raft ops. Apiserver burns CPU on watch storms or excessive audit logging. Controller-manager spins on failed reconciles (e.g., stuck finalizers). The workflow identifies the PID->Container mapping via crictl (standard CRI), executes etcd maintenance if DB > 2GB (default quota warning), restarts stateless controllers to clear local caches/loops, and validates via mpstat. Restarting kubelet is the nuclear option to force pod recreation if systemd units fail.", "safetyChecks": [{"check": "Verify etcd cluster health (HEALTHY status on all members) before and after compaction/defrag.", "passed": true}, {"check": "Confirm kube-apiserver, kube-controller-manager, kube-scheduler pods report ''Running'' status with 0 restarts post-intervention.", "passed": true}, {"check": "Validate CPU utilization drops below 70% sustained for 5 minutes via mpstat/top.", "passed": true}, {"check": "Ensure no leadership thrashing in controller-manager/scheduler logs (leader election events < 1/min).", "passed": true}], "incidentTitle": "High CPU Utilization on Control Plane", "confidenceScore": 85, "rejectionReason": "skipping", "proposedCommands": ["ssh root@192.168.100.101 \"top -b -n 1 | head -20\"", "ssh root@192.168.100.101 \"pidstat -u -p ALL 1 3 | awk ''$8 ~ /kube|etcd/ {print $0}''\"", "ssh root@192.168.100.101 \"crictl ps --name kube-apiserver --name kube-controller-manager --name kube-scheduler --name etcd -o table\"", "ssh root@192.168.100.101 \"ETCD_PID=$(crictl inspect $(crictl ps --name etcd -q) 2>/dev/null | jq -r ''.info.pid'') && [ -n \"$ETCD_PID\" ] && nsenter -t $ETCD_PID -m -- etcdctl endpoint status --cluster -w table 2>/dev/null || echo ''etcdctl not accessible via nsenter, trying local''\"", "ssh root@192.168.100.101 \"etcdctl endpoint status --cluster --write-out=table 2>/dev/null || ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key endpoint status --cluster --write-out=table\"", "ssh root@192.168.100.101 \"ETCD_DB_SIZE=$(ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key endpoint status --write-out=json 2>/dev/null | jq -r ''.[0].Status.dbSize'') && echo \"ETCD DB Size: $ETCD_DB_SIZE bytes\"\"", "ssh root@192.168.100.101 \"if [ -n \"$ETCD_DB_SIZE\" ] && [ \"$ETCD_DB_SIZE\" -gt 2147483648 ]; then echo ''ETCD DB > 2GB, triggering compaction and defrag''; ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key compact $(ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key endpoint status --write-out=json | jq -r ''.[0].Status.revision'') 2>/dev/null; ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key defrag 2>/dev/null; fi\"", "ssh root@192.168.100.101 \"APISERVER_PID=$(crictl inspect $(crictl ps --name kube-apiserver -q) 2>/dev/null | jq -r ''.info.pid'') && [ -n \"$APISERVER_PID\" ] && nsenter -t $APISERVER_PID -m -- cat /proc/$(pgrep -f kube-apiserver)/status 2>/dev/null | grep -E ''VmRSS|Threads'' || echo ''Apiserver PID NS enter failed''\"", "ssh root@192.168.100.101 \"journalctl -u kubelet --since \"-15m\" -p err..crit --no-pager | tail -20\"", "ssh root@192.168.100.101 \"crictl logs $(crictl ps --name kube-controller-manager -q) --tail=50 2>/dev/null | grep -i -E ''error|warn|reconcile|loop'' | head -10\"", "ssh root@192.168.100.101 \"systemctl restart kube-controller-manager kube-scheduler 2>/dev/null || systemctl restart kubelet\"", "ssh root@192.168.100.101 \"sleep 30\"", "ssh root@192.168.100.101 \"top -b -n 1 | head -10\"", "ssh root@192.168.100.101 \"mpstat 1 3\""], "synthesizerOutput": {"kbTitle": "SOP: High CPU Utilization Diagnosis & Remediation on Kubernetes Control Plane Node", "draftKbId": "KB-SOP-NEW", "trendInsight": "Synthesized SOP containing 14 resolution steps starting with SSH connection.", "resolutionSteps": ["ssh root@192.168.100.101 \"top -b -n 1 | head -20\"", "ssh root@192.168.100.101 \"pidstat -u -p ALL 1 3 | awk ''$8 ~ /kube|etcd/ {print $0}''\"", "ssh root@192.168.100.101 \"crictl ps --name kube-apiserver --name kube-controller-manager --name kube-scheduler --name etcd -o table\"", "ssh root@192.168.100.101 \"ETCD_PID=$(crictl inspect $(crictl ps --name etcd -q) 2>/dev/null | jq -r ''.info.pid'') && [ -n \"$ETCD_PID\" ] && nsenter -t $ETCD_PID -m -- etcdctl endpoint status --cluster -w table 2>/dev/null || echo ''etcdctl not accessible via nsenter, trying local''\"", "ssh root@192.168.100.101 \"etcdctl endpoint status --cluster --write-out=table 2>/dev/null || ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key endpoint status --cluster --write-out=table\"", "ssh root@192.168.100.101 \"ETCD_DB_SIZE=$(ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key endpoint status --write-out=json 2>/dev/null | jq -r ''.[0].Status.dbSize'') && echo \"ETCD DB Size: $ETCD_DB_SIZE bytes\"\"", "ssh root@192.168.100.101 \"if [ -n \"$ETCD_DB_SIZE\" ] && [ \"$ETCD_DB_SIZE\" -gt 2147483648 ]; then echo ''ETCD DB > 2GB, triggering compaction and defrag''; ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key compact $(ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key endpoint status --write-out=json | jq -r ''.[0].Status.revision'') 2>/dev/null; ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key defrag 2>/dev/null; fi\"", "ssh root@192.168.100.101 \"APISERVER_PID=$(crictl inspect $(crictl ps