d -u {username} &>/dev/null || useradd -m -s /bin/bash {username}\"\nssh root@192.168.100.101 \"echo ''{username}:{password}'' | chpasswd\"\nssh root@192.168.100.101 \"echo ''{username} ALL=(ALL) NOPASSWD: {sudo_command}'' > /etc/sudoers.d/99-{username}\"\nssh root@192.168.100.101 \"chmod 440 /etc/sudoers.d/99-{username}\"\nssh root@192.168.100.101 \"visudo -c\"\nssh root@192.168.100.101 \"sudo -u {username} sudo -l | grep -q ''{sudo_command}'' && echo ''Sudo rule verified for {username}''\""}, "kbArticleReference": "KB_NEW"}') ON CONFLICT DO NOTHING;
